    @staticmethod
    def _path_is_relative_to(path: Path, parent: Path) -> bool:
        try:
            path.relative_to(parent)
        except ValueError:
            return False
        return True

    @classmethod
    def _runtime_release_summary(cls) -> dict[str, object]:
        working_directory = Path.cwd().resolve()
        expected_source_root = (working_directory / "backend" / "src").resolve()
        package_file = Path(str(getattr(fin_ops_platform, "__file__", ""))).resolve()
        pythonpath_entries = [entry for entry in os.environ.get("PYTHONPATH", "").split(os.pathsep) if entry]
        release_metadata_path = working_directory / "RELEASE.json"
        release_metadata: dict[str, object] | None = None
        release_metadata_error: str | None = None
        if release_metadata_path.exists():
            try:
                raw_metadata = json.loads(release_metadata_path.read_text(encoding="utf-8"))
                if isinstance(raw_metadata, dict):
                    release_metadata = raw_metadata
                else:
                    release_metadata_error = "RELEASE.json must contain an object."
            except Exception as exc:
                release_metadata_error = str(exc)

        is_release_runtime = (
            cls._path_is_relative_to(working_directory, Path("/opt/fin-ops/releases"))
            or release_metadata_path.exists()
        )
        problems: list[str] = []
        if is_release_runtime and not cls._path_is_relative_to(package_file, expected_source_root):
            problems.append("package_import_path_mismatch")
        if is_release_runtime and release_metadata is None:
            problems.append("release_metadata_missing_or_invalid")

        return {
            "working_directory": str(working_directory),
            "package_file": str(package_file),
            "expected_source_root": str(expected_source_root),
            "pythonpath": pythonpath_entries,
            "release_metadata_path": str(release_metadata_path),
            "release_metadata": release_metadata,
            "release_metadata_error": release_metadata_error,
            "is_release_runtime": is_release_runtime,
            "consistent": not problems,
            "problems": problems,
        }

    def _health_payload(self) -> dict[str, object]:
        payload = self.readiness_summary()
        payload["seed_counts"] = {
            key: len(value) for key, value in self._seed_payload.items() if isinstance(value, list)
        }
        payload["module_boundaries"] = {
            "app": ["http entrypoint", "routing", "readiness checks"],
            "domain": ["enums", "core finance models", "status machine boundaries"],
            "services": [
                "audit trail",
                "seed data",
                "imports",
                "matching",
                "ledgers",
                "integrations",
                "workbench v2 contracts",
                "tax offset api",
                "etc invoice management",
            ],
            "planned": ["costing"],
        }
        payload["api_performance"] = self._api_performance_recorder.summary()
        payload["workbench_api_self_test"] = self._workbench_api_self_test()
        return payload

    def _workbench_api_self_test(self) -> dict[str, object]:
        scope_key = "all"
        repository = getattr(self, "_workbench_sql_read_repository", None)
        get_summary = getattr(repository, "get_workbench_summary", None)
        get_groups_page = getattr(repository, "get_workbench_groups_page", None)
        if not callable(get_summary) or not callable(get_groups_page):
            return {
                "scope_key": scope_key,
                "status": "unavailable",
                "summary_status": "unavailable",
                "summary_counts": {},
                "groups": {},
                "errors": ["workbench_sql_read_repository_unavailable"],
            }
        errors: list[str] = []
        summary_status = "unknown"
        summary_counts: dict[str, object] = {}
        try:
            summary_payload = get_summary(scope_key=scope_key)
            if isinstance(summary_payload, dict):
                summary_status = str(summary_payload.get("read_model_status") or "fresh")
                raw_summary = summary_payload.get("summary")
                if isinstance(raw_summary, dict):
                    summary_counts = {
                        key: raw_summary.get(key)
                        for key in ("paired_count", "open_count", "oa_count", "bank_count", "invoice_count")
                        if key in raw_summary
                    }
            else:
                summary_status = "missing"
                errors.append("summary_missing")
        except Exception as exc:
            summary_status = "error"
            errors.append(f"summary:{str(exc) or exc.__class__.__name__}")
        groups: dict[str, object] = {}
        for zone in ("paired", "open"):
            try:
                page_payload = get_groups_page(
                    scope_key=scope_key,
                    zone=zone,
                    page=1,
                    page_size=50,
                    detail_level="summary",
                )
                if not isinstance(page_payload, dict):
                    groups[zone] = {"status": "missing", "total": 0, "returned_count": 0}
                    errors.append(f"{zone}:groups_missing")
                    continue
                raw_groups = page_payload.get("groups")
                groups[zone] = {
                    "status": str(page_payload.get("read_model_status") or "fresh"),
                    "total": page_payload.get("total", 0),
                    "returned_count": len(raw_groups) if isinstance(raw_groups, list) else 0,
                }
            except Exception as exc:
                groups[zone] = {"status": "error", "total": 0, "returned_count": 0}
                errors.append(f"{zone}:{str(exc) or exc.__class__.__name__}")
        nonfresh_statuses = [
            str(value.get("status"))
            for value in groups.values()
            if isinstance(value, dict) and str(value.get("status") or "fresh") != "fresh"
        ]
        status = "ok"
        if errors:
            status = "error"
        elif summary_status != "fresh" or nonfresh_statuses:
            status = "stale"
        return {
            "scope_key": scope_key,
            "status": status,
            "summary_status": summary_status,
            "summary_counts": summary_counts,
            "groups": groups,
            "errors": errors,
        }

    def _handle_workbench_prototype(self) -> Response:
        prototype_path = Path(__file__).resolve().parents[4] / "web" / "prototypes" / "reconciliation-workbench-v2.html"
        return Response(
            status_code=int(HTTPStatus.OK),
            body=prototype_path.read_text(encoding="utf-8"),
            headers={"Content-Type": "text/html; charset=utf-8"},
        )

    def _handle_api_workbench(
        self,
        month: str | None,
        *,
        page: str | None = None,
        page_size: str | None = None,
        status: str | None = None,
        source_kind: str | None = None,
        search: str | None = None,
    ) -> Response:
        current_month = month or "all"
        sql_response = self._handle_api_workbench_from_sql_read_model(
            current_month,
            page=page,
            page_size=page_size,
            status=status,
            source_kind=source_kind,
            search=search,
        )
        if sql_response is not None:
            return sql_response
        if self._requires_sql_read_model_runtime():
            scope_key = self._workbench_read_model_scope_key(current_month)
            self._enqueue_workbench_read_model_refresh(scope_key, reason="api_sql_repository_unavailable")
            return self._json_response(
                HTTPStatus.SERVICE_UNAVAILABLE,
                {
                    "error": "read_model_unavailable",
                    "read_model_status": "unavailable",
                    "scope_key": scope_key,
                    "message": "Workbench SQL read model repository is not configured for production runtime.",
                },
            )
        return self._json_response(HTTPStatus.OK, self._build_api_workbench_payload(current_month))

    def _handle_api_workbench_from_sql_read_model(
        self,
        month: str,
        *,
        page: str | None = None,
        page_size: str | None = None,
        status: str | None = None,
        source_kind: str | None = None,
        search: str | None = None,
    ) -> Response | None:
        repository = getattr(self, "_workbench_sql_read_repository", None)
        get_view = getattr(repository, "get_workbench_view", None)
        if not callable(get_view):
            return None
        scope_key = self._workbench_read_model_scope_key(month)
        view = get_view(
            scope_key=scope_key,
            page=page,
            page_size=page_size,
            status=status,
            source_kind=source_kind,
            search=search,
        )
        if not isinstance(view, dict):
            self._enqueue_workbench_read_model_refresh(scope_key, reason="api_miss")
            return self._json_response(
                HTTPStatus.ACCEPTED,
                {
                    "read_model_status": "refreshing",
                    "scope_key": scope_key,
                    "message": "Workbench read model is missing; refresh has been enqueued.",
                },
            )
        payload = dict(view.get("payload") if isinstance(view.get("payload"), dict) else {})
        oa_sync_refresh_reason = self._workbench_sql_view_oa_sync_refresh_reason(view)
        if oa_sync_refresh_reason:
            self._enqueue_oa_projection_sync_refresh(
                scope_key,
                reason=oa_sync_refresh_reason,
            )
            payload["read_model_status"] = "refreshing"
            payload["read_model_scope_key"] = scope_key
            payload["read_model_refresh_reason"] = oa_sync_refresh_reason
            current_parser_version = self._current_oa_attachment_invoice_parser_version()
            if current_parser_version:
                payload["oa_attachment_invoice_parser_version"] = current_parser_version
            current_projection_version = self._current_oa_projection_sync_version()
            if current_projection_version:
                payload["oa_projection_sync_version"] = current_projection_version
            if view.get("generated_at"):
                payload["read_model_generated_at"] = view.get("generated_at")
            if isinstance(view.get("rows_page"), dict):
                payload["rows_page"] = view.get("rows_page")
            return self._json_response(HTTPStatus.ACCEPTED, payload)
        refresh_status = str(view.get("refresh_status") or view.get("cache_status") or "fresh")
        stale_reasons = self._workbench_sql_read_model_stale_reasons(
            view.get("source_versions"),
            scope_key=scope_key,
        )
        if stale_reasons:
            refresh_status = "stale"
            payload["read_model_stale_reasons"] = stale_reasons
        if refresh_status != "fresh":
            self._enqueue_workbench_read_model_refresh(scope_key, reason="api_stale")
        payload["read_model_status"] = refresh_status
        payload["read_model_scope_key"] = scope_key
        if view.get("generated_at"):
            payload["read_model_generated_at"] = view.get("generated_at")
        if isinstance(view.get("rows_page"), dict):
            payload["rows_page"] = view.get("rows_page")
        return self._json_response(HTTPStatus.OK, payload)

    def _handle_api_workbench_summary(self, month: str | None) -> Response:
        current_month = month or "all"
        repository = getattr(self, "_workbench_sql_read_repository", None)
        get_summary = getattr(repository, "get_workbench_summary", None)
        scope_key = self._workbench_read_model_scope_key(current_month)
        if not callable(get_summary):
            self._emit_workbench_read_model_status_metric(
                endpoint="/api/workbench/summary",
                scope_key=scope_key,
                read_model_status="unavailable",
                reason="repository_unavailable",
            )
            return self._json_response(
                HTTPStatus.SERVICE_UNAVAILABLE,
                {
                    "error": "read_model_unavailable",
                    "read_model_status": "unavailable",
                    "scope_key": scope_key,
                    "message": "Workbench SQL summary repository is not configured.",
                },
            )
        try:
            payload = get_summary(scope_key=scope_key)
        except Exception as error:
            if self._is_missing_workbench_groups_read_model_error(error):
                self._emit_workbench_read_model_status_metric(
                    endpoint="/api/workbench/summary",
                    scope_key=scope_key,
                    read_model_status="unavailable",
                    reason="migration_missing",
                )
                return self._json_response(
                    HTTPStatus.SERVICE_UNAVAILABLE,
                    {
                        "error": "read_model_unavailable",
                        "read_model_status": "unavailable",
                        "scope_key": scope_key,
                        "message": "Workbench SQL groups read model table is not migrated.",
                    },
                )
            raise
        if not isinstance(payload, dict):
            self._enqueue_workbench_read_model_refresh(scope_key, reason="api_summary_miss")
            self._emit_workbench_read_model_status_metric(
                endpoint="/api/workbench/summary",
                scope_key=scope_key,
                read_model_status="refreshing",
                reason="api_summary_miss",
            )
            return self._json_response(
                HTTPStatus.ACCEPTED,
                {
                    "month": current_month,
                    "scope_key": scope_key,
                    "summary": {
                        "oa_count": 0,
                        "bank_count": 0,
                        "invoice_count": 0,
                        "paired_count": 0,
                        "open_count": 0,
                        "exception_count": 0,
                    },
                    "read_model_status": "refreshing",
                    "generated_at": None,
                },
            )
        payload = dict(payload)
        stale_reasons = self._workbench_sql_read_model_stale_reasons(
            payload.get("source_versions"),
            scope_key=scope_key,
        )
        if stale_reasons:
            payload["read_model_status"] = "stale"
            payload["read_model_stale_reasons"] = [
                *list(payload.get("read_model_stale_reasons") if isinstance(payload.get("read_model_stale_reasons"), list) else []),
                *stale_reasons,
            ]
            self._enqueue_workbench_read_model_refresh(scope_key, reason="api_summary_source_versions_stale")
        if "oa_status" not in payload:
            oa_status_payload = getattr(getattr(self, "_workbench_query_service", None), "oa_status_payload", None)
            if callable(oa_status_payload):
                payload["oa_status"] = Application._serialize_value(oa_status_payload())
        summary_status = str(payload.get("read_model_status") or "fresh")
        if summary_status != "fresh":
            self._emit_workbench_read_model_status_metric(
                endpoint="/api/workbench/summary",
                scope_key=scope_key,
                read_model_status=summary_status,
                reason="sql_status",
            )
        return self._json_response(HTTPStatus.OK, payload)

    def _handle_api_workbench_groups(
        self,
        month: str | None,
        *,
        zone: str | None,
        page: str | None = None,
        page_size: str | None = None,
        status: str | None = None,
        source_kind: str | None = None,
        search: str | None = None,
        search_mode: str | None = None,
        search_by_pane: str | None = None,
        sort: str | None = None,
        detail_level: str | None = None,
        column_filters: str | None = None,
        time_filters: str | None = None,
    ) -> Response:
        current_month = month or "all"
        normalized_zone = str(zone or "").strip()
        if normalized_zone not in {"open", "paired"}:
            return self._json_response(
                HTTPStatus.BAD_REQUEST,
                {"error": "invalid_workbench_zone", "message": "zone must be open or paired."},
            )
        normalized_detail_level = self._normalize_workbench_group_detail_level(detail_level)
        normalized_search_mode = self._normalize_workbench_group_search_mode(search_mode)
        try:
            normalized_column_filters = self._normalize_workbench_group_json_query_param(column_filters, "column_filters")
            normalized_time_filters = self._normalize_workbench_group_json_query_param(time_filters, "time_filters")
            normalized_search_by_pane = self._normalize_workbench_group_json_query_param(search_by_pane, "search_by_pane")
        except ValueError as error:
            return self._json_response(
                HTTPStatus.BAD_REQUEST,
                {"error": "invalid_workbench_groups_query", "message": str(error)},
            )
        repository = getattr(self, "_workbench_sql_read_repository", None)
        get_groups_page = getattr(repository, "get_workbench_groups_page", None)
        scope_key = self._workbench_read_model_scope_key(current_month)
        if not callable(get_groups_page):
            self._emit_workbench_read_model_status_metric(
                endpoint="/api/workbench/groups",
                scope_key=scope_key,
                read_model_status="unavailable",
                reason="repository_unavailable",
            )
            return self._json_response(
                HTTPStatus.SERVICE_UNAVAILABLE,
                {
                    "error": "read_model_unavailable",
                    "read_model_status": "unavailable",
                    "scope_key": scope_key,
                    "message": "Workbench SQL groups repository is not configured.",
                },
            )
        redis_helper = getattr(getattr(self, "_runtime_repositories", None), "redis_helper", None)
        refresh_status_payload: dict[str, object] | None = None
        get_refresh_status = getattr(repository, "get_workbench_refresh_status", None)
        if callable(get_refresh_status):
            raw_refresh_status = get_refresh_status(scope_key=scope_key)
            if isinstance(raw_refresh_status, dict):
                refresh_status_payload = self._workbench_refresh_status_with_source_freshness(
                    raw_refresh_status,
                    scope_key=scope_key,
                )
                if str(refresh_status_payload.get("read_model_status") or "fresh") != "fresh":
                    self._enqueue_workbench_read_model_refresh(scope_key, reason="api_groups_source_versions_stale")
        get_cached = getattr(redis_helper, "get_json", None)
        get_text = getattr(redis_helper, "get_text", None)
        set_text = getattr(redis_helper, "set_text", None)
        version_key = self._workbench_groups_redis_version_key(scope_key)
        redis_cache_version = get_text(version_key) if callable(get_text) else None
        cache_key = self._workbench_groups_redis_cache_key_from_version(
            cache_version=redis_cache_version,
            scope_key=scope_key,
            zone=normalized_zone,
            page=page,
            page_size=page_size,
            status=status,
            source_kind=source_kind,
            search=search,
            search_mode=normalized_search_mode,
            search_by_pane=normalized_search_by_pane,
            sort=sort,
            detail_level=normalized_detail_level,
            column_filters=normalized_column_filters,
            time_filters=normalized_time_filters,
        )
        can_use_groups_redis_cache = (
            refresh_status_payload is None
            or str(refresh_status_payload.get("read_model_status") or "fresh") == "fresh"
        )
        if cache_key and callable(get_cached) and can_use_groups_redis_cache:
            cached = get_cached(cache_key)
            if isinstance(cached, dict):
                payload = dict(cached.get("payload") if isinstance(cached.get("payload"), dict) else cached)
                payload["read_model_status"] = "fresh"
                payload["read_model_scope_key"] = scope_key
                return self._json_response(HTTPStatus.OK, payload)
        if cache_key is None:
            cache_key = self._workbench_groups_redis_cache_key(
                repository=repository,
                scope_key=scope_key,
                zone=normalized_zone,
                page=page,
                page_size=page_size,
                status=status,
                source_kind=source_kind,
                search=search,
                search_mode=normalized_search_mode,
                search_by_pane=normalized_search_by_pane,
                sort=sort,
                detail_level=normalized_detail_level,
                column_filters=normalized_column_filters,
                time_filters=normalized_time_filters,
            )
        if cache_key and callable(get_cached) and can_use_groups_redis_cache:
            if callable(set_text):
                parsed_version = self._workbench_groups_redis_cache_version_from_key(cache_key)
                if parsed_version:
                    set_text(version_key, parsed_version, ttl_seconds=self._workbench_groups_redis_ttl_seconds())
            cached = get_cached(cache_key)
            if isinstance(cached, dict):
                payload = dict(cached.get("payload") if isinstance(cached.get("payload"), dict) else cached)
                payload["read_model_status"] = "fresh"
                payload["read_model_scope_key"] = scope_key
                return self._json_response(HTTPStatus.OK, payload)
        try:
            payload = get_groups_page(
                scope_key=scope_key,
                zone=normalized_zone,
                page=page,
                page_size=page_size,
                status=status,
                source_kind=source_kind,
                search=search,
                search_mode=normalized_search_mode,
                search_by_pane=normalized_search_by_pane,
                sort=sort,
                detail_level=normalized_detail_level,
                column_filters=normalized_column_filters,
                time_filters=normalized_time_filters,
            )
        except Exception as error:
            if self._is_missing_workbench_groups_read_model_error(error):
                self._emit_workbench_read_model_status_metric(
                    endpoint="/api/workbench/groups",
                    scope_key=scope_key,
                    read_model_status="unavailable",
                    reason="migration_missing",
                )
                return self._json_response(
                    HTTPStatus.SERVICE_UNAVAILABLE,
                    {
                        "error": "read_model_unavailable",
                        "read_model_status": "unavailable",
                        "scope_key": scope_key,
                        "message": "Workbench SQL groups read model table is not migrated.",
                    },
                )
            raise
        if not isinstance(payload, dict):
            self._enqueue_workbench_read_model_refresh(scope_key, reason="api_groups_miss")
            self._emit_workbench_read_model_status_metric(
                endpoint="/api/workbench/groups",
                scope_key=scope_key,
                read_model_status="refreshing",
                reason="api_groups_miss",
            )
            return self._json_response(
                HTTPStatus.ACCEPTED,
                {
                    "month": current_month,
                    "scope_key": scope_key,
                    "zone": normalized_zone,
                    "page": 1,
                    "page_size": 50,
                    "total": 0,
                    "has_more": False,
                    "groups": [],
                    "read_model_status": "refreshing",
                },
            )
        payload = dict(payload)
        payload["read_model_scope_key"] = scope_key
        stale_reasons = self._workbench_sql_read_model_stale_reasons(
            payload.get("source_versions"),
            scope_key=scope_key,
        )
        if stale_reasons:
            payload["read_model_status"] = "stale"
            payload["read_model_stale_reasons"] = [
                *list(payload.get("read_model_stale_reasons") if isinstance(payload.get("read_model_stale_reasons"), list) else []),
                *stale_reasons,
            ]
        groups_status = str(payload.get("read_model_status") or "fresh")
        if groups_status != "fresh":
            self._enqueue_workbench_read_model_refresh(scope_key, reason="api_groups_stale")
            self._emit_workbench_read_model_status_metric(
                endpoint="/api/workbench/groups",
                scope_key=scope_key,
                read_model_status=groups_status,
                reason="sql_status",
            )
        set_cached = getattr(redis_helper, "set_json", None)
        if cache_key and callable(set_cached) and payload.get("read_model_status") == "fresh":
            set_cached(cache_key, {"payload": payload}, ttl_seconds=self._workbench_groups_redis_ttl_seconds())
        return self._json_response(HTTPStatus.OK, payload)

    def _handle_api_workbench_group_detail(
        self,
        month: str | None,
        *,
        zone: str | None,
        group_id: str | None,
    ) -> Response:
        current_month = month or "all"
        normalized_zone = str(zone or "").strip()
        normalized_group_id = str(group_id or "").strip()
        if normalized_zone not in {"open", "paired"}:
            return self._json_response(
                HTTPStatus.BAD_REQUEST,
                {"error": "invalid_workbench_zone", "message": "zone must be open or paired."},
            )
        if not normalized_group_id:
            return self._json_response(
                HTTPStatus.BAD_REQUEST,
                {"error": "invalid_workbench_group_detail_request", "message": "group_id is required."},
            )
        repository = getattr(self, "_workbench_sql_read_repository", None)
        get_group_detail = getattr(repository, "get_workbench_group_detail", None)
        scope_key = self._workbench_read_model_scope_key(current_month)
        if not callable(get_group_detail):
            self._emit_workbench_read_model_status_metric(
                endpoint="/api/workbench/groups/detail",
                scope_key=scope_key,
                read_model_status="unavailable",
                reason="repository_unavailable",
            )
            return self._json_response(
                HTTPStatus.SERVICE_UNAVAILABLE,
                {
                    "error": "read_model_unavailable",
                    "read_model_status": "unavailable",
                    "scope_key": scope_key,
                    "message": "Workbench SQL group detail repository is not configured.",
                },
            )
        try:
            group = get_group_detail(scope_key=scope_key, zone=normalized_zone, group_id=normalized_group_id)
        except Exception as error:
            if self._is_missing_workbench_groups_read_model_error(error):
                self._emit_workbench_read_model_status_metric(
                    endpoint="/api/workbench/groups/detail",
                    scope_key=scope_key,
                    read_model_status="unavailable",
                    reason="migration_missing",
                )
                return self._json_response(
                    HTTPStatus.SERVICE_UNAVAILABLE,
                    {
                        "error": "read_model_unavailable",
                        "read_model_status": "unavailable",
                        "scope_key": scope_key,
                        "message": "Workbench SQL groups read model table is not migrated.",
                    },
                )
            raise
        if not isinstance(group, dict):
            return self._json_response(
                HTTPStatus.NOT_FOUND,
                {
                    "error": "workbench_group_not_found",
                    "scope_key": scope_key,
                    "zone": normalized_zone,
                    "group_id": normalized_group_id,
                },
            )
        return self._json_response(
            HTTPStatus.OK,
            {
                "month": current_month,
                "scope_key": scope_key,
                "zone": normalized_zone,
                "group_id": normalized_group_id,
                "group": group,
                "read_model_status": "fresh",
            },
        )

    def _handle_api_workbench_refresh_status(self, month: str | None) -> Response:
        current_month = month or "all"
        repository = getattr(self, "_workbench_sql_read_repository", None)
        get_refresh_status = getattr(repository, "get_workbench_refresh_status", None)
        scope_key = self._workbench_read_model_scope_key(current_month)
        if not callable(get_refresh_status):
            return self._json_response(
                HTTPStatus.SERVICE_UNAVAILABLE,
                {
                    "error": "read_model_unavailable",
                    "read_model_status": "unavailable",
                    "scope_key": scope_key,
                    "message": "Workbench SQL refresh status repository is not configured.",
                },
            )
        payload = get_refresh_status(scope_key=scope_key)
        if isinstance(payload, dict):
            payload = self._workbench_refresh_status_with_source_freshness(payload, scope_key=scope_key)
        return self._json_response(HTTPStatus.OK, self._normalize_workbench_refresh_status_payload(
            payload if isinstance(payload, dict) else {},
            scope_key=scope_key,
            fallback_status="unavailable" if not isinstance(payload, dict) else "fresh",
        ))

    def _handle_api_workbench_events(self, month: str | None) -> Response:
        current_month = month or "all"
        scope_key = self._workbench_read_model_scope_key(current_month)

        def event_stream() -> Iterable[str]:
            while True:
                status_payload = self._workbench_refresh_status_payload_for_scope(scope_key)
                event_name = self._workbench_refresh_status_event_name(status_payload)
                yield self._app_health_service.serialize_sse_event(event_name, status_payload)
                yield self._app_health_service.serialize_sse_event(
                    "heartbeat",
                    {
                        "scope_key": scope_key,
                        "generated_at": status_payload.get("generated_at"),
                        "read_model_status": status_payload.get("read_model_status"),
                    },
                )
                sleep(5)

        return Response(
            status_code=int(HTTPStatus.OK),
            body=event_stream(),
            stream=True,
            headers={
                "Content-Type": "text/event-stream; charset=utf-8",
                "Cache-Control": "no-cache, no-transform",
                "Connection": "keep-alive",
                "X-Accel-Buffering": "no",
                "Access-Control-Allow-Origin": "*",
                "Access-Control-Allow-Headers": "Content-Type",
                "Access-Control-Allow-Methods": "GET, POST, PUT, PATCH, DELETE, OPTIONS",
            },
        )

    def _workbench_refresh_status_payload_for_scope(self, scope_key: str) -> dict[str, object]:
        repository = getattr(self, "_workbench_sql_read_repository", None)
        get_refresh_status = getattr(repository, "get_workbench_refresh_status", None)
        if not callable(get_refresh_status):
            return self._normalize_workbench_refresh_status_payload(
                {},
                scope_key=scope_key,
                fallback_status="unavailable",
            )
        payload = get_refresh_status(scope_key=scope_key)
        if isinstance(payload, dict):
            payload = self._workbench_refresh_status_with_source_freshness(payload, scope_key=scope_key)
        return self._normalize_workbench_refresh_status_payload(
            payload if isinstance(payload, dict) else {},
            scope_key=scope_key,
            fallback_status="unavailable" if not isinstance(payload, dict) else "fresh",
        )

    @staticmethod
    def _normalize_workbench_refresh_status_payload(
        payload: dict[str, object],
        *,
        scope_key: str,
        fallback_status: str = "fresh",
    ) -> dict[str, object]:
        dirty_scopes = payload.get("dirty_scopes") if isinstance(payload.get("dirty_scopes"), list) else []
        running_scopes = payload.get("running_scopes") if isinstance(payload.get("running_scopes"), list) else []
        dirty_statuses = {
            str(scope.get("status") or "").strip().lower()
            for scope in dirty_scopes
            if isinstance(scope, dict)
        }
        raw_status = str(payload.get("read_model_status") or payload.get("status") or fallback_status).strip().lower()
        if dirty_statuses.intersection({"failed", "dead_lettered"}):
            read_model_status = "failed"
        elif raw_status in {"failed", "error"}:
            read_model_status = "failed"
        elif dirty_statuses.intersection({"pending", "processing", "queued", "running"}):
            read_model_status = "refreshing"
        elif raw_status in {"refreshing", "rebuilding", "pending", "processing", "queued", "running"}:
            read_model_status = "refreshing"
        elif raw_status in {"stale", "dirty"}:
            read_model_status = "stale"
        elif raw_status == "unavailable":
            read_model_status = "unavailable"
        else:
            read_model_status = "fresh"

        last_error = payload.get("last_error")
        if not last_error:
            last_error = next(
                (
                    scope.get("last_error")
                    for scope in dirty_scopes
                    if isinstance(scope, dict) and scope.get("last_error")
                ),
                None,
            )
        read_model_version = (
            payload.get("active_generation_id")
            or payload.get("read_model_version")
            or payload.get("source_version")
            or payload.get("version")
            or next(
                (
                    scope.get("source_version")
                    for scope in dirty_scopes
                    if isinstance(scope, dict) and scope.get("source_version") is not None
                ),
                None,
            )
        )
        generated_at = payload.get("generated_at") or payload.get("read_model_generated_at")
        return {
            **payload,
            "scope_key": str(payload.get("scope_key") or scope_key or "all"),
            "read_model_status": read_model_status,
            "generated_at": generated_at,
            "active_generation_id": payload.get("active_generation_id"),
            "building_generation_id": payload.get("building_generation_id"),
            "failed_generation_id": payload.get("failed_generation_id"),
            "read_model_version": read_model_version,
            "dirty_scopes": dirty_scopes,
            "running_scopes": running_scopes,
            "processed_count": payload.get("processed_count") if payload.get("processed_count") is not None else None,
            "total_count": payload.get("total_count") if payload.get("total_count") is not None else None,
            "worker_lag_seconds": payload.get("worker_lag_seconds") if payload.get("worker_lag_seconds") is not None else None,
            "last_error": last_error,
            "retryable": bool(read_model_status in {"failed", "stale", "unavailable"}),
        }

    @staticmethod
    def _workbench_refresh_status_event_name(payload: dict[str, object]) -> str:
        status = str(payload.get("read_model_status") or "").strip().lower()
        if status == "fresh":
            return "workbench.read_model.completed"
        if status == "failed":
            return "workbench.read_model.failed"
        if status in {"refreshing", "stale"}:
            return "workbench.read_model.progress"
        return "workbench.read_model.progress"

    @staticmethod
    def _is_missing_workbench_groups_read_model_error(error: Exception) -> bool:
        message = str(error).lower()
        return (
            (
                "read_model.workbench_groups" in message
                or "read_model.workbench_summary" in message
                or "read_model.workbench_generations" in message
            )
            and ("does not exist" in message or "undefinedtable" in error.__class__.__name__.lower())
        )

    @staticmethod
    def _is_missing_bank_account_balance_read_model_error(error: Exception) -> bool:
        message = str(error).lower()
        return (
            "read_model.bank_account_balances" in message
            and ("does not exist" in message or "undefinedtable" in error.__class__.__name__.lower())
        )

    def _workbench_groups_redis_cache_key(
        self,
        *,
        repository: object,
        scope_key: str,
        zone: str,
        page: str | None = None,
        page_size: str | None = None,
        status: str | None,
        source_kind: str | None,
        search: str | None,
        search_mode: str | None = None,
        search_by_pane: dict[str, object] | None = None,
        sort: str | None,
        detail_level: str | None,
        column_filters: dict[str, object] | None = None,
        time_filters: dict[str, object] | None = None,
    ) -> str | None:
        cache_version_loader = getattr(repository, "workbench_groups_cache_version", None)
        if not callable(cache_version_loader):
            return None
        cache_version = cache_version_loader(scope_key=scope_key)
        if not cache_version:
            return None
        key_payload = {
            "workbench_read_model_schema_version": WORKBENCH_READ_MODEL_SCHEMA_VERSION,
            "scope": scope_key,
            "zone": zone,
            "page": page or "1",
            "page_size": page_size or "50",
            "status": status or "",
            "source_kind": source_kind or "",
            "search": search or "",
            "search_mode": self._normalize_workbench_group_search_mode(search_mode),
            "search_by_pane": self._stable_json_value(search_by_pane or {}),
            "sort": sort or "",
            "detail_level": self._normalize_workbench_group_detail_level(detail_level),
            "column_filters": self._stable_json_value(column_filters or {}),
            "time_filters": self._stable_json_value(time_filters or {}),
            "filter_semantics": "linked_context_v1",
        }
        digest = hashlib.sha256(json.dumps(key_payload, ensure_ascii=False, sort_keys=True).encode("utf-8")).hexdigest()[:16]
        return f"workbench:{cache_version}:groups:{digest}"

    @staticmethod
    def _workbench_groups_redis_version_key(scope_key: str) -> str:
        safe_scope_key = str(scope_key or "all").strip() or "all"
        return f"workbench:groups:version:{safe_scope_key}"

    @staticmethod
    def _workbench_groups_redis_cache_version_from_key(cache_key: str) -> str | None:
        parts = str(cache_key or "").split(":")
        if len(parts) >= 3 and parts[0] == "workbench" and parts[2] == "groups":
            return parts[1]
        return None

    def _workbench_groups_redis_cache_key_from_version(
        self,
        *,
        cache_version: str | None,
        scope_key: str,
        zone: str,
        page: str | None,
        page_size: str | None,
        status: str | None,
        source_kind: str | None,
        search: str | None,
        search_mode: str | None = None,
        search_by_pane: dict[str, object] | None = None,
        sort: str | None,
        detail_level: str | None,
        column_filters: dict[str, object] | None = None,
        time_filters: dict[str, object] | None = None,
    ) -> str | None:
        if not cache_version:
            return None
        key_payload = {
            "workbench_read_model_schema_version": WORKBENCH_READ_MODEL_SCHEMA_VERSION,
            "scope": scope_key,
            "zone": zone,
            "page": page or "1",
            "page_size": page_size or "50",
            "status": status or "",
            "source_kind": source_kind or "",
            "search": search or "",
            "search_mode": self._normalize_workbench_group_search_mode(search_mode),
            "search_by_pane": self._stable_json_value(search_by_pane or {}),
            "sort": sort or "",
            "detail_level": self._normalize_workbench_group_detail_level(detail_level),
            "column_filters": self._stable_json_value(column_filters or {}),
            "time_filters": self._stable_json_value(time_filters or {}),
            "filter_semantics": "linked_context_v1",
        }
        digest = hashlib.sha256(json.dumps(key_payload, ensure_ascii=False, sort_keys=True).encode("utf-8")).hexdigest()[:16]
        return f"workbench:{cache_version}:groups:{digest}"

    @staticmethod
    def _normalize_workbench_group_json_query_param(value: str | None, name: str) -> dict[str, object]:
        raw_value = str(value or "").strip()
        if not raw_value:
            return {}
        try:
            parsed = json.loads(raw_value)
        except json.JSONDecodeError as error:
            raise ValueError(f"{name} must be valid JSON object.") from error
        if not isinstance(parsed, dict):
            raise ValueError(f"{name} must be a JSON object.")
        return Application._stable_json_value(parsed)

    @staticmethod
    def _normalize_workbench_group_search_mode(value: str | None) -> str:
        normalized = str(value or "").strip().lower()
        return "linked_context" if normalized == "linked_context" else "pane"

    @staticmethod
    def _stable_json_value(value: object) -> object:
        if isinstance(value, dict):
            return {
                str(key): Application._stable_json_value(value[key])
                for key in sorted(value, key=lambda item: str(item))
                if value[key] is not None
            }
        if isinstance(value, list):
            normalized_items = [Application._stable_json_value(item) for item in value]
            if all(not isinstance(item, (dict, list)) for item in normalized_items):
                return sorted(normalized_items, key=lambda item: json.dumps(item, ensure_ascii=False, sort_keys=True))
            return normalized_items
        return value

    @staticmethod
    def _normalize_workbench_group_detail_level(detail_level: str | None) -> str:
        normalized = str(detail_level or "full").strip().lower()
        return "summary" if normalized == "summary" else "full"

    @staticmethod
    def _workbench_groups_redis_ttl_seconds() -> int:
        raw_value = os.getenv("FIN_OPS_WORKBENCH_GROUPS_REDIS_TTL_SECONDS", "600").strip()
        try:
            return min(900, max(60, int(raw_value)))
        except ValueError:
            return 600

    @staticmethod
    def _app_health_workbench_status_cache_ttl_seconds() -> float:
        raw_value = os.getenv("FIN_OPS_APP_HEALTH_WORKBENCH_STATUS_CACHE_TTL_SECONDS", "2").strip()
        try:
            return min(10.0, max(0.0, float(raw_value)))
        except ValueError:
            return 2.0

    def _enqueue_workbench_read_model_refresh(self, scope_key: str, *, reason: str) -> None:
        queue_repository = getattr(getattr(self, "_runtime_repositories", None), "queue_repository", None)
        enqueue = getattr(queue_repository, "enqueue_read_model_refresh", None)
        if not callable(enqueue):
            return
        enqueue(scope_type="workbench", scope_key=scope_key, reason=reason)

    def _handle_api_oa_sync_status(self) -> Response:
        return self._json_response(HTTPStatus.OK, self._oa_sync_service.status_payload())

    def _handle_api_app_health(self, headers: dict[str, str] | None) -> Response:
        started_at = monotonic()
        session, error_response = self._resolve_app_health_session(headers)
        if error_response is not None:
            return error_response
        assert session is not None
        snapshot = self._build_app_health_snapshot(session, started_at=started_at)
        return self._json_response(HTTPStatus.OK, snapshot)

    def _handle_api_app_health_stream(self, headers: dict[str, str] | None) -> Response:
        session, error_response = self._resolve_app_health_session(headers)
        if error_response is not None:
            return error_response
        assert session is not None

        def event_stream() -> Iterable[str]:
            while True:
                started_at = monotonic()
                snapshot = self._build_app_health_snapshot(session, started_at=started_at)
                heartbeat = {"generated_at": snapshot.get("generated_at")}
                yield self._app_health_service.serialize_sse_event("app_health", snapshot)
                yield self._app_health_service.serialize_sse_event("heartbeat", heartbeat)
                sleep(5)

        return Response(
            status_code=int(HTTPStatus.OK),
            body=event_stream(),
            stream=True,
            headers={
                "Content-Type": "text/event-stream; charset=utf-8",
                "Cache-Control": "no-cache, no-transform",
                "Connection": "keep-alive",
                "X-Accel-Buffering": "no",
                "Access-Control-Allow-Origin": "*",
                "Access-Control-Allow-Headers": "Content-Type",
                "Access-Control-Allow-Methods": "GET, POST, PUT, PATCH, DELETE, OPTIONS",
            },
        )

    def _handle_api_operations_app_health_dashboard(self, headers: dict[str, str] | None) -> Response:
        _, admin_error = self._resolve_admin_session(headers)
        if admin_error is not None:
            return admin_error
        connection = getattr(self._state_store, "_connection", None)
        if connection is None:
            return self._json_response(
                HTTPStatus.SERVICE_UNAVAILABLE,
                {
                    "error": "postgres_required",
                    "message": "AppHealth dashboard requires PostgreSQL runtime metrics.",
                },
            )
        service = OperationsDashboardService(
            connection,
            api_performance_recorder=self._api_performance_recorder,
        )
        return self._json_response(HTTPStatus.OK, service.build_payload())

    def _resolve_app_health_session(
        self,
        headers: dict[str, str] | None,
    ) -> tuple[OARequestSession | None, Response | None]:
        try:
            session = resolve_oa_request_session(
                headers,
                identity_service=self._oa_identity_service,
                access_control_service=self._access_control_service,
            )
            if not session.allowed:
                raise ForbiddenOAAccessError("当前 OA 账户未被授权访问财务运营平台。")
        except UnauthorizedOASessionError as error:
            return None, self._json_response(
                HTTPStatus.UNAUTHORIZED,
                {
                    "error": "invalid_oa_session",
                    "message": str(error) or "缺少 OA 登录态，请从 OA 系统进入。",
                },
            )
        except OASessionExpiredError as error:
            return None, self._json_response(
                HTTPStatus.UNAUTHORIZED,
                {
                    "error": "invalid_oa_session",
                    "message": str(error) or "OA 登录状态已过期。",
                },
            )
        except ForbiddenOAAccessError as error:
            return None, self._json_response(
                HTTPStatus.FORBIDDEN,
                {
                    "error": "forbidden",
                    "message": str(error) or "当前 OA 账户未被授权访问财务运营平台。",
                },
            )
        except OAIdentityConfigurationError as error:
            return None, self._json_response(
                HTTPStatus.SERVICE_UNAVAILABLE,
                {
                    "error": "oa_identity_unavailable",
                    "message": str(error) or "OA 身份服务未配置。",
                },
            )
        except OAIdentityServiceError as error:
            return None, self._json_response(
                HTTPStatus.BAD_GATEWAY,
                {
                    "error": "oa_identity_lookup_failed",
                    "message": str(error) or "OA 身份解析失败。",
                },
            )
        return session, None

    def _build_app_health_snapshot(self, session: OARequestSession, *, started_at: float) -> dict[str, object]:
        owner_user_id = session.identity.username or session.identity.user_id or "web_finance_user"
        active_jobs = self._background_job_service.list_active_jobs(owner_user_id, include_system=True)
        attention_jobs = self._background_job_service.list_attention_jobs(owner_user_id, include_system=True)
        oa_sync_payload = self._app_health_oa_sync_payload()
        state_store_info = {
            "storage_mode": self._state_store.storage_mode if self._state_store is not None else "memory",
            "backend": self._state_store.storage_backend if self._state_store is not None else "memory",
        }
        snapshot_without_alerts = self._app_health_service.build_snapshot(
            session=session,
            active_jobs=active_jobs,
            oa_sync_payload=oa_sync_payload,
            state_store_info=state_store_info,
            rebuild_scheduled=self._is_oa_sync_rebuild_scheduled(),
            duration_ms=self._duration_ms(started_at),
            attention_jobs=attention_jobs,
            alerts={"active": [], "recent_recovered": []},
        )
        self._apply_workbench_generation_health(snapshot_without_alerts)
        alerts = self._app_health_alert_service.evaluate(snapshot_without_alerts)
        if self._state_store is not None:
            self._state_store.save_app_health_alerts(self._app_health_alert_service.snapshot())
        snapshot = self._app_health_service.build_snapshot(
            session=session,
            active_jobs=active_jobs,
            oa_sync_payload=oa_sync_payload,
            state_store_info=state_store_info,
            rebuild_scheduled=self._is_oa_sync_rebuild_scheduled(),
            duration_ms=self._duration_ms(started_at),
            attention_jobs=attention_jobs,
            alerts=alerts,
        )
        self._apply_workbench_generation_health(snapshot)
        self._emit_app_health_timing(snapshot)
        return snapshot

    def _apply_workbench_generation_health(self, snapshot: dict[str, object]) -> None:
        repository = getattr(self, "_workbench_sql_read_repository", None)
        if not callable(getattr(repository, "get_workbench_refresh_status", None)):
            return
        try:
            status_payload = self._cached_workbench_refresh_status(repository, scope_key="all")
        except Exception as exc:
            workbench_payload = snapshot.get("workbench_read_model")
            if not isinstance(workbench_payload, dict):
                workbench_payload = {}
                snapshot["workbench_read_model"] = workbench_payload
            workbench_payload["status"] = "error"
            workbench_payload["last_error"] = str(exc) or exc.__class__.__name__
            snapshot["status"] = "blocked"
            return
        if not isinstance(status_payload, dict):
            return
        read_model_status = str(status_payload.get("read_model_status") or "").strip().lower()
        consistency_status = str(status_payload.get("consistency_status") or "").strip().lower()
        if read_model_status != "failed" and consistency_status != "failed":
            return
        workbench_payload = snapshot.get("workbench_read_model")
        if not isinstance(workbench_payload, dict):
            workbench_payload = {}
            snapshot["workbench_read_model"] = workbench_payload
        workbench_payload.update(
            {
                "status": "error",
                "read_model_status": read_model_status or "failed",
                "consistency_status": consistency_status or "failed",
                "active_generation_id": status_payload.get("active_generation_id"),
                "failed_generation_id": status_payload.get("failed_generation_id"),
                "last_error": status_payload.get("last_error"),
                "consistency_failures": status_payload.get("consistency_failures")
                if isinstance(status_payload.get("consistency_failures"), list)
                else [],
            }
        )
        dependencies = snapshot.get("dependencies")
        if isinstance(dependencies, dict):
            dependencies["workbench_read_model"] = {
                "status": "unavailable",
                "message": status_payload.get("last_error") or "Workbench read model generation consistency failed.",
            }
        snapshot["status"] = "blocked"

    def _cached_workbench_refresh_status(self, repository: object, *, scope_key: str) -> dict[str, object]:
        ttl_seconds = self._app_health_workbench_status_cache_ttl_seconds()
        get_refresh_status = getattr(repository, "get_workbench_refresh_status", None)
        if not callable(get_refresh_status):
            return {}
        if ttl_seconds <= 0:
            payload = get_refresh_status(scope_key=scope_key)
            return dict(payload) if isinstance(payload, dict) else {}
        cache_key = f"workbench_refresh_status:{scope_key}"
        cache = getattr(self, "_app_health_workbench_status_cache", None)
        if not isinstance(cache, dict):
            cache = {}
            setattr(self, "_app_health_workbench_status_cache", cache)
        now = monotonic()
        cached = cache.get(cache_key)
        if isinstance(cached, tuple) and len(cached) == 2:
            expires_at, payload = cached
            if isinstance(expires_at, (int, float)) and now < float(expires_at) and isinstance(payload, dict):
                return dict(payload)
        payload = get_refresh_status(scope_key=scope_key)
        normalized = dict(payload) if isinstance(payload, dict) else {}
        cache[cache_key] = (now + ttl_seconds, normalized)
        return normalized

    @staticmethod
    def _emit_app_health_timing(snapshot: dict[str, object]) -> None:
        metrics = snapshot.get("metrics") if isinstance(snapshot.get("metrics"), dict) else {}
        log_payload = {
            "event": "app_health.snapshot",
            "status": snapshot.get("status"),
            "duration_ms": metrics.get("app_health_duration_ms"),
            "dirty_scope_count": metrics.get("dirty_scope_count"),
            "background_jobs_running_count": metrics.get("background_jobs_running_count"),
            "active_alert_count": metrics.get("active_alert_count"),
        }
        print(json.dumps(log_payload, ensure_ascii=False))

    def _app_health_oa_sync_payload(self) -> dict[str, object]:
        payload = self._serialize_value(self._oa_sync_service.status_payload())
        if not isinstance(payload, dict):
            payload = {}
        matching_dirty_scopes = self._workbench_matching_dirty_scope_service.list_dirty_scopes()
        with self._workbench_matching_run_lock:
            matching_running_scopes = sorted(self._workbench_matching_running_scope_months)
        if matching_running_scopes:
            payload["workbench_matching_running_scopes"] = matching_running_scopes
        if not matching_dirty_scopes:
            return payload
        payload["workbench_matching_dirty_scopes"] = matching_dirty_scopes
        raw_dirty_scopes = [
            str(scope).strip()
            for scope in list(payload.get("dirty_scopes") or [])
            if str(scope).strip()
        ]
        matching_scope_months = [
            str(entry.get("scope_month") or "").strip()
            for entry in matching_dirty_scopes
            if str(entry.get("scope_month") or "").strip()
        ]
        payload["dirty_scopes"] = sorted(dict.fromkeys([*raw_dirty_scopes, *matching_scope_months]))
        age_payload = payload.get("dirty_scope_age_seconds")
        dirty_scope_ages = dict(age_payload) if isinstance(age_payload, dict) else {}
        now = datetime.now(UTC)
        for entry in matching_dirty_scopes:
            scope_month = str(entry.get("scope_month") or "").strip()
            if not scope_month:
                continue
            dirty_scope_ages[scope_month] = AppHealthService.seconds_since(entry.get("updated_at"), now)
        payload["dirty_scope_age_seconds"] = dirty_scope_ages
        if not payload.get("message"):
            payload["message"] = "关联台自动配对存在待重算月份。"
        return payload

    def _is_oa_sync_rebuild_scheduled(self) -> bool:
        with self._oa_sync_rebuild_lock:
            return self._oa_sync_rebuild_scheduled

    @staticmethod
    def _is_workbench_read_model_rebuild_job(job: object) -> bool:
        return AppHealthService.is_workbench_read_model_rebuild_job(job)

    def _workbench_write_freshness_guard(self) -> Response | None:
        oa_sync_payload = self._oa_sync_service.status_payload()
        dirty_scopes = [
            str(scope)
            for scope in list(oa_sync_payload.get("dirty_scopes", []) or [])
            if str(scope).strip()
        ]
        if not dirty_scopes and not self._is_oa_sync_rebuild_scheduled():
            return None
        return self._json_response(
            HTTPStatus.CONFLICT,
            {
                "error": "workbench_stale",
                "message": "关联台正在同步，请刷新完成后再操作。",
                "dirty_scopes": dirty_scopes,
            },
        )

    def _handle_api_search(
        self,
        *,
        q: str,
        scope: str | None,
        month: str | None,
        project_name: str | None,
        status: str | None,
        limit: str | None,
    ) -> Response:
        resolved_scope = scope or "all"
        resolved_month = month or "all"
        resolved_status = status or None
        try:
            resolved_limit = int(limit) if limit not in (None, "") else 20
        except (TypeError, ValueError):
            return self._json_response(
                HTTPStatus.BAD_REQUEST,
                {"error": "invalid_search_request", "message": "limit must be an integer."},
            )
        if resolved_scope not in SEARCH_SUPPORTED_SCOPES:
            return self._json_response(
                HTTPStatus.BAD_REQUEST,
                {"error": "invalid_search_request", "message": "scope must be all, oa, bank, or invoice."},
            )
        if resolved_month != "all" and not SEARCH_MONTH_RE.match(resolved_month):
            return self._json_response(
                HTTPStatus.BAD_REQUEST,
                {"error": "invalid_search_request", "message": "month must be all or YYYY-MM."},
            )
        if resolved_status is not None and resolved_status not in SEARCH_SUPPORTED_STATUSES:
            return self._json_response(
                HTTPStatus.BAD_REQUEST,
                {
                    "error": "invalid_search_request",
                    "message": "status must be paired, open, ignored, or processed_exception.",
                },
            )
        sql_payload = self._get_search_payload_from_sql_read_model(
            q=q,
            scope=resolved_scope,
            month=resolved_month,
            project_name=project_name,
            status=resolved_status,
            limit=resolved_limit,
        )
        if sql_payload is not None:
            status_code = HTTPStatus.ACCEPTED if sql_payload.get("read_model_status") == "refreshing" and not sql_payload.get("summary", {}).get("total") else HTTPStatus.OK
            return self._json_response(status_code, sql_payload)
        payload = self._search_service.search(
            q=q,
            scope=resolved_scope,
            month=resolved_month,
            project_name=project_name,
            status=resolved_status,
            limit=resolved_limit,
        )
        return self._json_response(HTTPStatus.OK, payload)

    def _get_search_payload_from_sql_read_model(
        self,
        *,
        q: str,
        scope: str,
        month: str,
        project_name: str | None,
        status: str | None,
        limit: int,
    ) -> dict[str, object] | None:
        repository = getattr(self, "_search_sql_read_repository", None)
        search_index = getattr(repository, "search_index", None)
        if not callable(search_index):
            return None
        payload = search_index(q=q, scope=scope, month=month, project_name=project_name, status=status, limit=limit)
        scope_key = month if month != "all" else "all"
        if not isinstance(payload, dict):
            self._enqueue_search_read_model_refresh(scope_key, reason="api_miss")
            return {
                "query": q,
                "filters": {"scope": scope, "month": month, "project_name": project_name or None, "status": status, "limit": limit},
                "summary": {"total": 0, "oa": 0, "bank": 0, "invoice": 0},
                "oa_results": [],
                "bank_results": [],
                "invoice_results": [],
                "read_model_status": "refreshing",
                "read_model_scope_key": scope_key,
            }
        refresh_status = str(payload.get("refresh_status") or "fresh")
        if refresh_status != "fresh":
            self._enqueue_search_read_model_refresh(scope_key, reason="api_stale")
        stale_reasons = source_version_mismatch_reasons(
            expected=self._search_index_expected_source_versions(),
            actual=payload.get("source_versions") if isinstance(payload.get("source_versions"), dict) else {},
        )
        if stale_reasons:
            refresh_status = "stale"
            self._enqueue_search_read_model_refresh(scope_key, reason="api_source_versions_stale")
        result = dict(payload)
        result["read_model_status"] = refresh_status
        result["read_model_scope_key"] = scope_key
        if stale_reasons:
            result["read_model_stale_reasons"] = stale_reasons
        result.pop("refresh_status", None)
        return result

    def _search_index_expected_source_versions(self) -> dict[str, object]:
        return {
            "search_index_schema_version": "2026-05-search-index-v1",
            "workbench_read_model_schema_version": WORKBENCH_SQL_PROJECTION_SCHEMA_VERSION,
            "bank_auto_tag_rules_version": self._current_bank_auto_tag_rules_version(),
            "oa_attachment_invoice_parser_version": self._current_oa_attachment_invoice_parser_version(),
            "oa_projection_sync_version": self._current_oa_projection_sync_version(),
        }

    def _enqueue_search_read_model_refresh(self, scope_key: str, *, reason: str) -> bool:
        queue_repository = getattr(getattr(self, "_runtime_repositories", None), "queue_repository", None)
        enqueue = getattr(queue_repository, "enqueue_read_model_refresh", None)
        if not callable(enqueue):
            return False
        enqueue(scope_type="search", scope_key=scope_key, reason=reason)
        return True

    def _handle_api_etc_import(self, body: str | bytes | None, headers: dict[str, str] | None) -> Response:
        return self._json_response(
            HTTPStatus.GONE,
            {
                "error": "etc_direct_import_removed",
                "message": "Use /api/etc/import/preview and /api/etc/import/confirm.",
            },
        )

    def _handle_api_etc_reconciliation_tasks(self) -> Response:
        return self._json_response(
            HTTPStatus.OK,
            {"tasks": [self._etc_reconciliation_task_payload(task) for task in self._etc_reconciliation_task_service.list_tasks()]},
        )

    def _handle_api_etc_reconciliation_ready_for_import(self) -> Response:
        ready_tasks = self._etc_reconciliation_task_service.list_ready_for_import_tasks()
        unavailable_tasks = [
            task
            for task in self._etc_reconciliation_task_service.list_tasks()
            if getattr(getattr(task, "status", ""), "value", getattr(task, "status", "")) != "ready_for_import"
        ]
        return self._json_response(
            HTTPStatus.OK,
            {
                "tasks": [self._etc_reconciliation_task_payload(task) for task in ready_tasks],
                "unavailableTasks": [self._etc_reconciliation_unavailable_task_payload(task) for task in unavailable_tasks],
            },
        )

    def _handle_api_etc_reconciliation_task_create(self, body: str | bytes | None) -> Response:
        payload, error = self._load_json_body(body)
        if error is not None:
            return error
        task = self._etc_reconciliation_task_service.create_task(
            title=str(payload.get("title") or "").strip(),
            created_by=str(payload.get("createdBy") or payload.get("created_by") or "web_finance_user"),
        )
        return self._json_response(HTTPStatus.CREATED, self._etc_reconciliation_task_payload(task))

    def _route_api_etc_reconciliation_task(
        self,
        method: str,
        route_path: str,
        body: str | bytes | None,
        headers: dict[str, str] | None,
    ) -> Response:
        relative = route_path.removeprefix("/api/etc/reconciliation-tasks/").strip("/")
        parts = [unquote(part) for part in relative.split("/") if part]
        if not parts:
            return self._json_response(HTTPStatus.NOT_FOUND, {"error": "unknown_reconciliation_task"})
        task_id = parts[0]
        if method == "GET" and len(parts) == 1:
            try:
                task = self._etc_reconciliation_task_service.get_task(task_id)
            except KeyError:
                return self._json_response(HTTPStatus.NOT_FOUND, {"error": "unknown_reconciliation_task"})
            return self._json_response(HTTPStatus.OK, self._etc_reconciliation_task_payload(task))
        if method == "DELETE" and len(parts) == 1:
            return self._handle_api_etc_reconciliation_task_delete(task_id, body)
        if method == "DELETE" and len(parts) == 3 and parts[1] == "source-files":
            return self._handle_api_etc_reconciliation_source_file_delete(task_id, parts[2], body)
        if method == "POST" and len(parts) == 2 and parts[1] == "credit-card-statement":
            return self._handle_api_etc_reconciliation_upload(
                task_id=task_id,
                source_kind=SourceFileKind.CREDIT_CARD_STATEMENT,
                body=body,
                headers=headers,
            )
        if method == "POST" and len(parts) == 2 and parts[1] == "ticket-root-files":
            return self._handle_api_etc_reconciliation_upload(
                task_id=task_id,
                source_kind=SourceFileKind.TICKET_ROOT,
                body=body,
                headers=headers,
            )
        if method == "POST" and len(parts) == 2 and parts[1] == "ticket-root-texts":
            return self._handle_api_etc_reconciliation_ticket_root_texts(task_id, body)
        if method == "POST" and len(parts) == 2 and parts[1] == "supplement-evidences":
            return self._handle_api_etc_reconciliation_upload(
                task_id=task_id,
                source_kind=SourceFileKind.SUPPLEMENT_EVIDENCE,
                body=body,
                headers=headers,
            )
        if method == "POST" and len(parts) == 3 and parts[1] == "supplement-evidences":
            return self._handle_api_etc_reconciliation_supplement_for_card_upload(
                task_id=task_id,
                item_id=parts[2],
                body=body,
                headers=headers,
            )
        if method == "PATCH" and len(parts) == 3 and parts[1] == "items":
            return self._handle_api_etc_reconciliation_item_patch(task_id, parts[2], body)
        if method == "POST" and len(parts) == 2 and parts[1] == "confirm":
            return self._handle_api_etc_reconciliation_confirm(task_id, body)
        if method == "POST" and len(parts) == 2 and parts[1] == "reopen":
            return self._handle_api_etc_reconciliation_reopen(task_id, body)
        if method == "POST" and len(parts) == 2 and parts[1] == "refresh-matches":
            return self._handle_api_etc_reconciliation_refresh_matches(task_id)
        if method == "DELETE" and len(parts) == 2 and parts[1] == "imported-invoices":
            return self._handle_api_etc_reconciliation_imported_invoices_delete(task_id, body)
        return self._json_response(HTTPStatus.NOT_FOUND, {"error": "unknown_reconciliation_task_route"})

    def _handle_api_etc_reconciliation_upload(
        self,
        *,
        task_id: str,
        source_kind: SourceFileKind,
        body: str | bytes | None,
        headers: dict[str, str] | None,
    ) -> Response:
        fields, files, error = self._load_multipart_body(body, headers)
        if error is not None:
            return error
        if not files:
            return self._json_response(HTTPStatus.BAD_REQUEST, {"error": "invalid_reconciliation_upload", "message": "file is required."})
        actor = (fields.get("actor") or ["web_finance_user"])[0]
        try:
            task = self._etc_reconciliation_task_service.get_task(task_id)
            expected_version = self._expected_version_from_fields(fields)
            if task.version != expected_version:
                raise ValueError("task_version_conflict")
            ticket_root_upload_modes: list[str] = []
            if source_kind == SourceFileKind.TICKET_ROOT:
                for upload in files:
                    wrong_slot_message = self._reconciliation_wrong_slot_message(
                        expected_source_kind=source_kind,
                        content=upload.content,
                    )
                    if wrong_slot_message:
                        return self._json_response(
                            HTTPStatus.BAD_REQUEST,
                            {
                                "error": "wrong_reconciliation_source_kind",
                                "message": wrong_slot_message,
                            },
                        )
                    ticket_root_upload_modes.append(_ticket_root_upload_source_mode(upload))
                self._validate_ticket_root_upload_source_mode(task=task, upload_modes=ticket_root_upload_modes)
            else:
                ticket_root_upload_modes = []
        except KeyError:
            return self._json_response(HTTPStatus.NOT_FOUND, {"error": "unknown_reconciliation_task"})
        except ValueError as error:
            return self._reconciliation_error_response(error)
        try:
            for upload_index, upload in enumerate(files):
                ticket_root_upload_mode = (
                    ticket_root_upload_modes[upload_index]
                    if source_kind == SourceFileKind.TICKET_ROOT and upload_index < len(ticket_root_upload_modes)
                    else ""
                )
                content_type = (
                    "text/plain; charset=utf-8"
                    if source_kind == SourceFileKind.TICKET_ROOT and ticket_root_upload_mode == "text_file"
                    else "application/octet-stream"
                )
                source_file = self._etc_reconciliation_task_service.store_uploaded_source_file(
                    task_id=task.task_id,
                    source_kind=source_kind,
                    original_name=upload.file_name,
                    content_type=content_type,
                    content=upload.content,
                    created_by=actor,
                )
                if source_kind == SourceFileKind.CREDIT_CARD_STATEMENT:
                    parse_result = CcbCreditCardStatementParser().parse_pdf_bytes(file_id=source_file.file_id, content=upload.content)
                elif source_kind == SourceFileKind.TICKET_ROOT:
                    if ticket_root_upload_mode == "text_file":
                        decoded_text = _decode_utf8_text(upload.content) or ""
                        parse_result = (
                            TicketRootClipboardTextParser().parse_text(file_id=source_file.file_id, text=decoded_text)
                            if _looks_like_ticket_root_clipboard_text(decoded_text)
                            else _ticket_root_text_file_not_trip_result(source_file.file_id)
                        )
                    else:
                        parse_result = TicketRootDocumentParser().parse_file(file_id=source_file.file_id, content=upload.content)
                else:
                    parse_result = SupplementEvidenceParser().parse_text(
                        file_id=source_file.file_id,
                        text=upload.content.decode("utf-8", errors="ignore"),
                        source_name=source_file.original_name,
                        evidence_kind_override=(fields.get("evidenceKind") or [None])[0],
                    )
                task = self._etc_reconciliation_task_service.apply_parse_result(task_id=task_id, parse_result=parse_result, actor=actor)
        except ValueError as error:
            return self._reconciliation_error_response(error)
        return self._json_response(HTTPStatus.OK, self._etc_reconciliation_task_payload(task))

    def _handle_api_etc_reconciliation_supplement_for_card_upload(
        self,
        *,
        task_id: str,
        item_id: str,
        body: str | bytes | None,
        headers: dict[str, str] | None,
    ) -> Response:
        fields, files, error = self._load_multipart_body(body, headers)
        if error is not None:
            return error
        if not files:
            return self._json_response(HTTPStatus.BAD_REQUEST, {"error": "invalid_reconciliation_upload", "message": "file is required."})
        actor = (fields.get("actor") or ["web_finance_user"])[0]
        try:
            expected_version = self._expected_version_from_fields(fields)
            task = self._etc_reconciliation_task_service.upload_supplement_evidences_for_card(
                task_id=task_id,
                item_id=item_id,
                expected_version=expected_version,
                actor=actor,
                files=[
                    {
                        "original_name": upload.file_name,
                        "content_type": "application/octet-stream",
                        "content": upload.content,
                    }
                    for upload in files
                ],
                note=(fields.get("note") or fields.get("reviewNote") or fields.get("reason") or [""])[0],
                evidence_kind_override=(fields.get("evidenceKind") or [None])[0],
            )
        except KeyError:
            return self._json_response(HTTPStatus.NOT_FOUND, {"error": "unknown_reconciliation_task"})
        except ValueError as error:
            return self._reconciliation_error_response(error)
        return self._json_response(HTTPStatus.OK, self._etc_reconciliation_task_payload(task))

    def _handle_api_etc_reconciliation_ticket_root_texts(
        self,
        task_id: str,
        body: str | bytes | None,
    ) -> Response:
        payload, error = self._load_json_body(body)
        if error is not None:
            return error
        entries = payload.get("entries")
        if not isinstance(entries, list) or not entries:
            return self._json_response(
                HTTPStatus.BAD_REQUEST,
                {"error": "invalid_ticket_root_text_entries", "message": "entries is required."},
            )
        try:
            task = self._etc_reconciliation_task_service.get_task(task_id)
            expected_version = self._expected_version_from_payload(payload)
            if task.version != expected_version:
                raise ValueError("task_version_conflict")
            if _has_ticket_root_text_file_source(task):
                raise ValueError("ticket_root_source_mode_conflict_text_file")
            if _has_ticket_root_document_source(task):
                raise ValueError("ticket_root_source_mode_conflict_pdf")
        except KeyError:
            return self._json_response(HTTPStatus.NOT_FOUND, {"error": "unknown_reconciliation_task"})
        except ValueError as value_error:
            return self._reconciliation_error_response(value_error)

        actor = str(payload.get("actor") or "web_finance_user")
        parser = TicketRootClipboardTextParser()
        try:
            for index, entry in enumerate(entries, start=1):
                if not isinstance(entry, dict):
                    return self._json_response(
                        HTTPStatus.BAD_REQUEST,
                        {"error": "invalid_ticket_root_text_entry", "message": "entry must be an object."},
                    )
                text = str(entry.get("text") or "")
                if not text.strip():
                    return self._json_response(
                        HTTPStatus.BAD_REQUEST,
                        {"error": "invalid_ticket_root_text_entry", "message": "text is required."},
                    )
                source_file = self._etc_reconciliation_task_service.store_uploaded_source_file(
                    task_id=task.task_id,
                    source_kind=SourceFileKind.TICKET_ROOT,
                    original_name=_ticket_root_clipboard_source_name(text, index=index),
                    content_type="text/plain; charset=utf-8",
                    content=text.encode("utf-8"),
                    created_by=actor,
                )
                parse_result = parser.parse_text(file_id=source_file.file_id, text=text)
                task = self._etc_reconciliation_task_service.apply_parse_result(
                    task_id=task_id,
                    parse_result=parse_result,
                    actor=actor,
                )
        except ValueError as value_error:
            return self._reconciliation_error_response(value_error)
        return self._json_response(HTTPStatus.OK, self._etc_reconciliation_task_payload(task))

