    def _handle_api_pending_invoice_attach_existing_confirm(
        self,
        transaction_id: str,
        body: str | bytes | None,
        headers: dict[str, str] | None,
    ) -> Response:
        payload, error = self._load_json_body(body)
        if error is not None:
            return error
        session = resolve_oa_request_session(
            headers,
            identity_service=self._oa_identity_service,
            access_control_service=self._access_control_service,
        )
        if not session.can_mutate_data:
            return self._json_response(
                HTTPStatus.FORBIDDEN,
                {"error": "permission_denied", "message": "当前账户没有选择已有发票权限。"},
            )
        actor_id = str(session.identity.username or "pending_invoice").strip()
        try:
            result = self._pending_invoice_application_service.confirm_attach_existing_invoice(
                transaction_id=transaction_id,
                payload=payload,
                actor_id=actor_id,
            )
        except PendingInvoiceError as exc:
            self._persist_state()
            return self._pending_invoice_error_response(exc)
        except Exception:
            self._persist_state()
            raise
        self._persist_state()
        return self._json_response(HTTPStatus.OK, result)

    def _handle_api_pending_invoice_rules(self, headers: dict[str, str] | None = None) -> Response:
        session, auth_error = self._resolve_pending_invoice_read_session(headers)
        if auth_error is not None:
            return auth_error
        settings = self._app_settings_service.get_settings_payload()
        rules_payload = self._pending_invoice_rules_payload(settings)
        rules_payload["permissions"] = {"can_save": bool(session.can_mutate_data) if session is not None else True}
        return self._json_response(
            HTTPStatus.OK,
            rules_payload,
        )

    def _handle_api_pending_invoice_rules_update(self, body: str | bytes | None, headers: dict[str, str] | None) -> Response:
        payload, error = self._load_json_body(body)
        if error is not None:
            return error
        try:
            session = resolve_oa_request_session(
                headers,
                identity_service=self._oa_identity_service,
                access_control_service=self._access_control_service,
            )
        except UnauthorizedOASessionError as exc:
            return self._json_response(HTTPStatus.UNAUTHORIZED, {"error": "unauthorized", "message": str(exc)})
        except ForbiddenOAAccessError as exc:
            return self._json_response(HTTPStatus.FORBIDDEN, {"error": "permission_denied", "message": str(exc)})
        if not session.can_mutate_data:
            return self._json_response(
                HTTPStatus.FORBIDDEN,
                {"error": "permission_denied", "message": "当前账户没有保存待找发票规则权限。"},
            )
        pending_invoice_tag_groups = payload.get("pending_invoice_tag_groups", payload)
        if not isinstance(pending_invoice_tag_groups, dict):
            return self._json_response(
                HTTPStatus.BAD_REQUEST,
                {"error": "invalid_pending_invoice_rules_request", "message": "pending_invoice_tag_groups must be an object."},
            )
        current = self._app_settings_service.get_settings_payload()
        access_control = current.get("access_control") if isinstance(current.get("access_control"), dict) else {}
        projects = current.get("projects") if isinstance(current.get("projects"), dict) else {}
        actor_id = str(session.identity.username or "pending_invoice_rules").strip()
        try:
            updated = self._app_settings_service.update_settings(
                completed_project_ids=list(projects.get("completed_project_ids") or projects.get("completed") or []),
                bank_account_mappings=list(current.get("bank_account_mappings") or []),
                allowed_usernames=list(access_control.get("allowed_usernames") or []),
                readonly_export_usernames=list(access_control.get("readonly_export_usernames") or []),
                admin_usernames=list(access_control.get("admin_usernames") or []),
                workbench_column_layouts=current.get("workbench_column_layouts") if isinstance(current.get("workbench_column_layouts"), dict) else {},
                oa_retention=current.get("oa_retention") if isinstance(current.get("oa_retention"), dict) else {},
                oa_import=current.get("oa_import") if isinstance(current.get("oa_import"), dict) else {},
                oa_invoice_offset=current.get("oa_invoice_offset") if isinstance(current.get("oa_invoice_offset"), dict) else {},
                bank_transaction_tags=current.get("bank_transaction_tags") if isinstance(current.get("bank_transaction_tags"), dict) else None,
                pending_invoice_tag_groups=pending_invoice_tag_groups,
                actor_id=actor_id or "pending_invoice_rules",
                after_bank_transaction_tag_settings_saved=self._finalize_bank_transaction_tag_settings_update,
            )
        except AppSettingsValidationError as exc:
            return self._json_response(HTTPStatus.BAD_REQUEST, {"error": exc.error_code, "message": str(exc)})
        if self._state_store is not None:
            self._persist_state()
        self._invalidate_pending_invoice_read_model_scopes(reason="pending_invoice_rules_update")
        rules_payload = self._pending_invoice_rules_payload(updated)
        rules_payload["permissions"] = {"can_save": True}
        return self._json_response(HTTPStatus.OK, rules_payload)

    @staticmethod
    def _pending_invoice_rules_payload(settings: dict[str, object]) -> dict[str, object]:
        tag_dictionary = settings.get("bank_transaction_tags") if isinstance(settings.get("bank_transaction_tags"), dict) else {}
        pending_groups = (
            settings.get("pending_invoice_tag_groups")
            if isinstance(settings.get("pending_invoice_tag_groups"), dict)
            else {}
        )
        groups = pending_groups.get("groups") if isinstance(pending_groups.get("groups"), dict) else {}
        tags = list(tag_dictionary.get("tags") or tag_dictionary.get("definitions") or []) if isinstance(tag_dictionary, dict) else []
        tags_by_code = {
            str(tag.get("code") or ""): tag
            for tag in tags
            if isinstance(tag, dict) and str(tag.get("code") or "").strip()
        }
        enriched_groups: dict[str, object] = {}
        for group_name in ("requires_invoice", "bank_statement_as_invoice", "no_invoice_required"):
            group = groups.get(group_name) if isinstance(groups, dict) and isinstance(groups.get(group_name), dict) else {}
            tag_codes = [str(code).strip() for code in list(group.get("tag_codes") or []) if str(code).strip()]
            enriched_groups[group_name] = {
                "tag_codes": tag_codes,
                "tags": [
                    {
                        "code": code,
                        "label": str((tags_by_code.get(code) or {}).get("label") or code),
                        "status": str((tags_by_code.get(code) or {}).get("status") or "active"),
                    }
                    for code in tag_codes
                ],
            }
        return {
            "version": int(pending_groups.get("version") or 1) if isinstance(pending_groups, dict) else 1,
            "groups": enriched_groups,
            "bank_transaction_tags": tag_dictionary,
            "pending_invoice_tag_groups": pending_groups,
        }

    def _handle_api_pending_invoice_export_preview(
        self,
        query: dict[str, list[str]],
        headers: dict[str, str] | None = None,
    ) -> Response:
        _session, auth_error = self._resolve_pending_invoice_read_session(headers)
        if auth_error is not None:
            return auth_error
        try:
            sql_rows_payload = self._get_pending_invoice_all_rows_from_sql_read_model(query)
            if isinstance(sql_rows_payload, Response):
                return sql_rows_payload
            if isinstance(sql_rows_payload, dict):
                payload = self._pending_invoice_query_service.export_preview_for_rows(
                    rows=list(sql_rows_payload.get("rows") or []),
                    filters=self._pending_invoice_query_kwargs(query),
                )
            else:
                payload = self._pending_invoice_query_service.export_preview(**self._pending_invoice_query_kwargs(query))
        except PendingInvoiceError as exc:
            return self._pending_invoice_error_response(exc)
        return self._json_response(HTTPStatus.OK, payload)

    def _handle_api_pending_invoice_export(
        self,
        query: dict[str, list[str]],
        headers: dict[str, str] | None = None,
    ) -> Response:
        session, auth_error = self._resolve_pending_invoice_read_session(headers)
        if auth_error is not None:
            return auth_error
        try:
            sql_rows_payload = self._get_pending_invoice_all_rows_from_sql_read_model(query)
            if isinstance(sql_rows_payload, Response):
                return sql_rows_payload
            if isinstance(sql_rows_payload, dict):
                filename, content = self._pending_invoice_query_service.export_for_rows(
                    rows=list(sql_rows_payload.get("rows") or []),
                )
            else:
                filename, content = self._pending_invoice_query_service.export(**self._pending_invoice_query_kwargs(query))
        except PendingInvoiceError as exc:
            return self._pending_invoice_error_response(exc)
        self._audit_service.record_action(
            actor_id=str(session.identity.username or "pending_invoice_export") if session is not None else "pending_invoice_export",
            action="pending_invoice_export_downloaded",
            entity_type="pending_invoice_export",
            entity_id=filename,
            metadata={"query": {key: values[0] for key, values in query.items() if values}},
        )
        return Response(
            status_code=int(HTTPStatus.OK),
            body=content,
            headers={
                "Content-Type": XLSX_MIME_TYPE,
                "Content-Disposition": _build_content_disposition(filename),
                "Access-Control-Allow-Origin": "*",
                "Access-Control-Allow-Headers": "Content-Type",
                "Access-Control-Allow-Methods": "GET, POST, PUT, PATCH, DELETE, OPTIONS",
            },
        )

    @staticmethod
    def _pending_invoice_query_kwargs(query: dict[str, list[str]]) -> dict[str, object]:
        return {
            "direction": query.get("direction", ["expense"])[0],
            "filter": query.get("filter", ["all"])[0],
            "date_from": query.get("date_from", [None])[0],
            "date_to": query.get("date_to", [None])[0],
            "keyword": query.get("keyword", [None])[0],
            "filters": query.get("filters", [None])[0],
            "sort_field": query.get("sort_field", [None])[0],
            "sort_direction": query.get("sort_direction", [None])[0],
        }

    def _resolve_pending_invoice_read_session(
        self,
        headers: dict[str, str] | None,
    ) -> tuple[OARequestSession | None, Response | None]:
        return self._resolve_fin_ops_read_session(headers, denied_message="当前账户没有访问待找发票页面权限。")

    def _resolve_bank_details_read_session(
        self,
        headers: dict[str, str] | None,
    ) -> tuple[OARequestSession | None, Response | None]:
        return self._resolve_fin_ops_read_session(headers, denied_message="当前账户没有访问银行明细页面权限。")

    def _resolve_fin_ops_read_session(
        self,
        headers: dict[str, str] | None,
        *,
        denied_message: str,
    ) -> tuple[OARequestSession | None, Response | None]:
        identity_service = getattr(self, "_oa_identity_service", None)
        access_control_service = getattr(self, "_access_control_service", None)
        if identity_service is None or access_control_service is None:
            return None, None
        try:
            session = resolve_oa_request_session(
                headers,
                identity_service=identity_service,
                access_control_service=access_control_service,
            )
        except OASessionExpiredError as error:
            return None, self._json_response(
                HTTPStatus.UNAUTHORIZED,
                {"error": "invalid_oa_session", "message": str(error) or "OA 登录状态已过期。"},
            )
        except UnauthorizedOASessionError as error:
            return None, self._json_response(
                HTTPStatus.UNAUTHORIZED,
                {"error": "invalid_oa_session", "message": str(error) or "缺少 OA 登录态，请从 OA 系统进入。"},
            )
        except ForbiddenOAAccessError as error:
            return None, self._json_response(
                HTTPStatus.FORBIDDEN,
                {"error": "permission_denied", "message": str(error) or "当前 OA 账户未被授权访问财务运营平台。"},
            )
        except OAIdentityConfigurationError as error:
            return None, self._json_response(
                HTTPStatus.SERVICE_UNAVAILABLE,
                {"error": "oa_identity_unavailable", "message": str(error) or "OA 身份服务未配置。"},
            )
        except OAIdentityServiceError as error:
            return None, self._json_response(
                HTTPStatus.BAD_GATEWAY,
                {"error": "oa_identity_lookup_failed", "message": str(error) or "OA 身份解析失败。"},
            )
        if not session.can_access_app:
            return None, self._json_response(
                HTTPStatus.FORBIDDEN,
                {"error": "permission_denied", "message": denied_message},
            )
        return session, None

    def _get_pending_invoice_all_rows_from_sql_read_model(
        self,
        query: dict[str, list[str]],
    ) -> dict[str, object] | Response | None:
        repository = getattr(self, "_pending_invoice_sql_read_repository", None)
        list_rows = getattr(repository, "list_pending_invoice_rows", None)
        if not callable(list_rows):
            return None
        page_size = 200
        first_query = {key: list(values) for key, values in query.items()}
        first_query["page"] = ["1"]
        first_query["page_size"] = [str(page_size)]
        first_payload = self._get_pending_invoice_rows_from_sql_read_model(first_query)
        if first_payload is None:
            return None
        if first_payload.get("read_model_status") != "fresh":
            return self._json_response(HTTPStatus.ACCEPTED, first_payload)
        rows = list(first_payload.get("rows") or [])
        pagination = first_payload.get("pagination") if isinstance(first_payload.get("pagination"), dict) else {}
        total = int(pagination.get("total") or len(rows))
        page = 2
        while len(rows) < total:
            page_query = {key: list(values) for key, values in query.items()}
            page_query["page"] = [str(page)]
            page_query["page_size"] = [str(page_size)]
            page_payload = self._get_pending_invoice_rows_from_sql_read_model(page_query)
            if not isinstance(page_payload, dict):
                return None
            if page_payload.get("read_model_status") != "fresh":
                return self._json_response(HTTPStatus.ACCEPTED, page_payload)
            page_rows = list(page_payload.get("rows") or [])
            if not page_rows:
                break
            rows.extend(page_rows)
            page += 1
        return {
            "direction": first_payload.get("direction"),
            "filter": first_payload.get("filter"),
            "rows": rows,
            "pagination": {"page": 1, "page_size": page_size, "total": total},
            "summary": first_payload.get("summary") if isinstance(first_payload.get("summary"), dict) else {},
            "read_model_status": "fresh",
            "read_model_scope_key": first_payload.get("read_model_scope_key"),
        }

    def _get_pending_invoice_rows_from_sql_read_model(self, query: dict[str, list[str]]) -> dict[str, object] | None:
        repository = getattr(self, "_pending_invoice_sql_read_repository", None)
        list_rows = getattr(repository, "list_pending_invoice_rows", None)
        if not callable(list_rows):
            return None
        direction = query.get("direction", [""])[0]
        filter_name = query.get("filter", ["all"])[0]
        normalized_direction = str(direction or "").strip()
        normalized_filter = str(filter_name or "all").strip() or "all"
        if normalized_direction not in {"expense", "income"}:
            raise PendingInvoiceError("invalid_direction", "direction must be expense or income.")
        if normalized_filter not in PENDING_INVOICE_VALID_FILTERS:
            raise PendingInvoiceError("invalid_filter", "filter must be all or a supported pending invoice group.")
        if normalized_direction == "income" and normalized_filter in PENDING_INVOICE_EXPENSE_FILTERS:
            raise PendingInvoiceError(
                "invalid_filter_for_income",
                "Income pending invoice rows do not support expense invoice tag filters.",
                status_code=HTTPStatus.BAD_REQUEST,
            )
        try:
            payload = list_rows(
                direction=normalized_direction,
                filter=normalized_filter,
                date_from=query.get("date_from", [None])[0],
                date_to=query.get("date_to", [None])[0],
                keyword=query.get("keyword", [None])[0],
                filters=query.get("filters", [None])[0],
                sort_field=query.get("sort_field", [None])[0],
                sort_direction=query.get("sort_direction", [None])[0],
                page=query.get("page", [1])[0],
                page_size=query.get("page_size", [50])[0],
            )
        except ValueError as exc:
            raise PendingInvoiceError("invalid_pending_invoice_query", str(exc)) from exc
        scope_key = self._pending_invoice_scope_key(direction=normalized_direction, filter_name=normalized_filter)
        if not isinstance(payload, dict):
            self._enqueue_pending_invoice_read_model_refresh(scope_key, reason="api_miss")
            return self._pending_invoice_refreshing_payload(
                direction=normalized_direction,
                filter_name=normalized_filter,
                scope_key=scope_key,
                query=query,
            )
        refresh_status = str(payload.get("refresh_status") or "fresh")
        if self._pending_invoice_sql_payload_requires_schema_refresh(payload):
            if refresh_status == "fresh":
                self._enqueue_pending_invoice_read_model_refresh(scope_key, reason="api_schema_stale")
            return self._pending_invoice_refreshing_payload(
                direction=normalized_direction,
                filter_name=normalized_filter,
                scope_key=scope_key,
                query=query,
                source_payload=payload,
            )
        if refresh_status != "fresh":
            result = self._pending_invoice_sql_payload_response(
                payload,
                read_model_status=refresh_status,
                scope_key=scope_key,
            )
            return result
        stale_reasons = source_version_mismatch_reasons(
            expected=self._pending_invoice_expected_source_versions(),
            actual=payload.get("source_versions") if isinstance(payload.get("source_versions"), dict) else {},
        )
        if stale_reasons:
            self._enqueue_pending_invoice_read_model_refresh(scope_key, reason="api_source_versions_stale")
            return self._pending_invoice_refreshing_payload(
                direction=normalized_direction,
                filter_name=normalized_filter,
                scope_key=scope_key,
                query=query,
                source_payload=payload,
                stale_reasons=stale_reasons,
            )
        result = self._pending_invoice_sql_payload_response(
            payload,
            read_model_status=refresh_status,
            scope_key=scope_key,
        )
        return result

    def _pending_invoice_sql_payload_response(
        self,
        payload: dict[str, object],
        *,
        read_model_status: str,
        scope_key: str,
    ) -> dict[str, object]:
        result = dict(payload)
        summary = result.get("summary")
        if isinstance(summary, dict) and not isinstance(summary.get("source_summary"), dict):
            direction, _sep, _filter_name = scope_key.partition(":")
            summary = dict(summary)
            summary["source_summary"] = self._pending_invoice_source_summary_for_query(
                direction=direction,
                query={},
                source_payload=result,
            )
            result["summary"] = summary
        rows = result.get("rows")
        pending_invoice_query_service = getattr(self, "_pending_invoice_query_service", None)
        normalizer = getattr(pending_invoice_query_service, "normalize_row_payloads", None)
        if isinstance(rows, list) and callable(normalizer):
            result["rows"] = normalizer([row for row in rows if isinstance(row, dict)])
        settings_service = getattr(self, "_app_settings_service", None)
        get_settings_payload = getattr(settings_service, "get_settings_payload", None)
        if callable(get_settings_payload):
            settings_payload = get_settings_payload()
            bank_transaction_tags = (
                settings_payload.get("bank_transaction_tags")
                if isinstance(settings_payload, dict)
                else None
            )
            if isinstance(bank_transaction_tags, dict):
                result["bank_transaction_tags"] = bank_transaction_tags
                result["bank_transaction_tags_version"] = int(
                    bank_transaction_tags.get("version") or result.get("bank_transaction_tags_version") or 1
                )
        result["read_model_status"] = read_model_status
        result["read_model_scope_key"] = scope_key
        result.pop("refresh_status", None)
        return result

    def _pending_invoice_refreshing_payload(
        self,
        *,
        direction: str,
        filter_name: str,
        scope_key: str,
        query: dict[str, list[str]],
        source_payload: dict[str, object] | None = None,
        stale_reasons: list[str] | None = None,
    ) -> dict[str, object]:
        payload: dict[str, object] = {
            "direction": direction,
            "filter": filter_name,
            "rows": [],
            "pagination": {"page": 1, "page_size": 50, "total": 0},
            "summary": {
                "total_rows": 0,
                "missing_invoice_rows": 0,
                "create_invoice_available_rows": 0,
                "source_summary": self._pending_invoice_source_summary_for_query(
                    direction=direction,
                    query=query,
                    source_payload=source_payload,
                ),
            },
            "bank_transaction_tags": {},
            "bank_transaction_tags_version": 1,
            "read_model_status": "refreshing",
            "read_model_scope_key": scope_key,
        }
        if stale_reasons:
            payload["read_model_stale_reasons"] = list(stale_reasons)
        return payload

    def _pending_invoice_expected_source_versions(self) -> dict[str, object]:
        settings_service = getattr(self, "_app_settings_service", None)
        get_settings_payload = getattr(settings_service, "get_settings_payload", None)
        settings = get_settings_payload() if callable(get_settings_payload) else {}
        if not isinstance(settings, dict):
            settings = {}
        pending_groups = settings.get("pending_invoice_tag_groups")
        bank_tags = settings.get("bank_transaction_tags")
        return {
            "pending_invoice_read_model_schema_version": "2026-05-pending-invoice-v1",
            "pending_invoice_tag_groups_version": (
                pending_groups.get("version") if isinstance(pending_groups, dict) else 1
            ),
            "bank_auto_tag_rules_version": (
                bank_tags.get("version") if isinstance(bank_tags, dict) else self._current_bank_auto_tag_rules_version()
            ),
            "oa_attachment_invoice_parser_version": self._current_oa_attachment_invoice_parser_version(),
            "oa_projection_sync_version": self._current_oa_projection_sync_version(),
        }

    def _pending_invoice_source_summary_for_query(
        self,
        *,
        direction: str,
        query: dict[str, list[str]],
        source_payload: dict[str, object] | None = None,
    ) -> dict[str, int]:
        summary = source_payload.get("summary") if isinstance(source_payload, dict) else None
        source_summary = summary.get("source_summary") if isinstance(summary, dict) else None
        if isinstance(source_summary, dict):
            return {
                "bank_transaction_rows": self._optional_int(source_summary.get("bank_transaction_rows")) or 0,
                "expense_rows": self._optional_int(source_summary.get("expense_rows")) or 0,
                "income_rows": self._optional_int(source_summary.get("income_rows")) or 0,
                "current_direction_rows": self._optional_int(source_summary.get("current_direction_rows")) or 0,
                "excluded_direction_rows": self._optional_int(source_summary.get("excluded_direction_rows")) or 0,
            }
        repository = getattr(self, "_pending_invoice_sql_read_repository", None)
        source_summary_loader = getattr(repository, "pending_invoice_source_summary", None)
        if callable(source_summary_loader):
            try:
                return source_summary_loader(
                    direction=direction,
                    date_from=query.get("date_from", [None])[0],
                    date_to=query.get("date_to", [None])[0],
                )
            except Exception:
                return {}
        return {}

    @staticmethod
    def _pending_invoice_sql_payload_requires_schema_refresh(payload: dict[str, object]) -> bool:
        rows = list(payload.get("rows") or [])
        if not rows:
            return False
        for row in rows:
            if not isinstance(row, dict):
                return True
            if not isinstance(row.get("invoice_acquisition_status"), dict):
                return True
            if not isinstance(row.get("input_invoices"), dict):
                return True
            if not isinstance(row.get("oa"), dict):
                return True
        return False

    @staticmethod
    def _pending_invoice_scope_key(*, direction: str, filter_name: str | None = None) -> str:
        normalized_direction = str(direction or "").strip()
        normalized_filter = str(filter_name or "all").strip() or "all"
        return f"{normalized_direction}:{normalized_filter}"

    def _enqueue_pending_invoice_read_model_refresh(self, scope_key: str, *, reason: str) -> bool:
        queue_repository = getattr(getattr(self, "_runtime_repositories", None), "queue_repository", None)
        enqueue = getattr(queue_repository, "enqueue_read_model_refresh", None)
        if not callable(enqueue):
            return False
        enqueue(scope_type="pending_invoice", scope_key=scope_key, reason=reason)
        return True

    def _handle_api_pending_invoice_manual_preview(self, body: str | bytes | None) -> Response:
        payload, error = self._load_json_body(body)
        if error is not None:
            return error
        try:
            preview = self._pending_invoice_application_service.preview_manual_invoice(payload)
        except PendingInvoiceError as exc:
            return self._pending_invoice_error_response(exc)
        return self._json_response(HTTPStatus.OK, preview)

    def _handle_api_pending_invoice_manual_confirm(
        self,
        body: str | bytes | None,
        headers: dict[str, str] | None,
    ) -> Response:
        payload, error = self._load_json_body(body)
        if error is not None:
            return error
        session = resolve_oa_request_session(
            headers,
            identity_service=self._oa_identity_service,
            access_control_service=self._access_control_service,
        )
        if not session.can_mutate_data:
            return self._json_response(
                HTTPStatus.FORBIDDEN,
                {"error": "permission_denied", "message": "当前账户没有手工补票权限。"},
            )
        actor_id = str(session.identity.username or "pending_invoice").strip()
        try:
            result = self._pending_invoice_application_service.confirm_manual_invoice(payload, actor_id=actor_id)
        except PendingInvoiceError as exc:
            self._persist_state()
            return self._pending_invoice_error_response(exc)
        except Exception:
            self._persist_state()
            raise
        self._persist_state()
        return self._json_response(HTTPStatus.OK, result)

    def _pending_invoice_error_response(self, exc: PendingInvoiceError) -> Response:
        payload: dict[str, object] = {"error": exc.error_code, "message": str(exc)}
        if exc.details:
            payload["details"] = exc.details
        return self._json_response(exc.status_code, payload)

    def _record_pending_invoice_manual_invoice_audit(self, event: dict[str, object]) -> None:
        action = str(event.get("action") or "pending_invoice_manual_invoice_confirmed")
        entity_type = str(event.get("entity_type") or event.get("source") or "")
        if not entity_type:
            entity_type = "pending_invoice_attach_existing_invoice" if action == "pending_invoice_attach_existing_invoice_confirmed" else "pending_invoice_manual_invoice"
        self._audit_service.record_action(
            actor_id=str(event.get("actor_id") or "pending_invoice"),
            action=action,
            entity_type=entity_type,
            entity_id=str(event.get("request_id") or event.get("invoice_id") or ""),
            metadata=dict(event),
        )

    def _finalize_pending_invoice_manual_invoice(self, event: dict[str, object]) -> None:
        affected_months = [str(month) for month in list(event.get("affected_months") or []) if str(month).strip()]
        action = str(event.get("action") or "pending_invoice_manual_invoice_confirmed")
        source = str(event.get("source") or event.get("entity_type") or "")
        if not source:
            source = "pending_invoice_attach_existing_invoice" if action == "pending_invoice_attach_existing_invoice_confirmed" else "pending_invoice_manual_invoice"
        self._execute_derived_data_lifecycle_event(
            action,
            months=affected_months,
            metadata={"source": source, **dict(event)},
        )
        projection = getattr(self, "_bank_details_relation_tag_projection_service", None)
        if projection is not None:
            try:
                setattr(projection, "_index_cache_key", "")
                setattr(projection, "_index_cache", {})
            except Exception:
                pass

    def _handle_api_workbench_ignored(self, month: str | None) -> Response:
        current_month = month or "all"
        return self._json_response(
            HTTPStatus.OK,
            {
                "month": current_month,
                "rows": self._build_api_workbench_ignored_rows_payload(current_month),
            },
        )

    def _handle_api_workbench_settings(self) -> Response:
        return self._json_response(HTTPStatus.OK, self._app_settings_service.get_settings_payload())

    def _handle_api_workbench_settings_update(
        self,
        body: str | bytes | None,
        headers: dict[str, str] | None,
    ) -> Response:
        payload, error = self._load_json_body(body)
        if error is not None:
            return error
        try:
            session = resolve_oa_request_session(
                headers,
                identity_service=self._oa_identity_service,
                access_control_service=self._access_control_service,
            )
        except UnauthorizedOASessionError as exc:
            return self._json_response(HTTPStatus.UNAUTHORIZED, {"error": "unauthorized", "message": str(exc)})
        except ForbiddenOAAccessError as exc:
            return self._json_response(HTTPStatus.FORBIDDEN, {"error": "permission_denied", "message": str(exc)})
        if not session.can_mutate_data:
            return self._json_response(
                HTTPStatus.FORBIDDEN,
                {"error": "permission_denied", "message": "当前账户没有保存设置权限。"},
            )
        completed_project_ids = payload.get("completed_project_ids", [])
        bank_account_mappings = payload.get("bank_account_mappings", [])
        allowed_usernames = payload.get("allowed_usernames", [])
        readonly_export_usernames = payload.get("readonly_export_usernames", [])
        admin_usernames = payload.get("admin_usernames", [])
        workbench_column_layouts = payload.get("workbench_column_layouts", {})
        oa_retention = payload.get("oa_retention", {})
        oa_invoice_offset = payload.get("oa_invoice_offset", {})
        oa_import = payload.get("oa_import", {})
        bank_transaction_tags = payload.get("bank_transaction_tags")
        pending_invoice_tag_groups = payload.get("pending_invoice_tag_groups")
        actor_id = str(session.identity.username or "workbench_settings").strip()
        previous_oa_invoice_offset = self._app_settings_service.get_settings_payload().get("oa_invoice_offset")
        if not isinstance(previous_oa_invoice_offset, dict):
            previous_oa_invoice_offset = {}
        if (
            not isinstance(completed_project_ids, list)
            or not isinstance(bank_account_mappings, list)
            or not isinstance(allowed_usernames, list)
            or not isinstance(readonly_export_usernames, list)
            or not isinstance(admin_usernames, list)
            or not isinstance(workbench_column_layouts, dict)
            or not isinstance(oa_retention, dict)
            or not isinstance(oa_import, dict)
            or not isinstance(oa_invoice_offset, dict)
        ):
            return self._json_response(
                HTTPStatus.BAD_REQUEST,
                {
                    "error": "invalid_workbench_settings_request",
                    "message": (
                        "completed_project_ids, bank_account_mappings, allowed_usernames, "
                        "readonly_export_usernames, and admin_usernames must be arrays, "
                        "and workbench_column_layouts, oa_retention, oa_import, and oa_invoice_offset must be objects."
                    ),
                },
            )
        if bank_transaction_tags is not None and not isinstance(bank_transaction_tags, dict):
            return self._json_response(
                HTTPStatus.BAD_REQUEST,
                {
                    "error": "invalid_workbench_settings_request",
                    "message": "bank_transaction_tags must be an object when provided.",
                },
            )
        if pending_invoice_tag_groups is not None and not isinstance(pending_invoice_tag_groups, dict):
            return self._json_response(
                HTTPStatus.BAD_REQUEST,
                {
                    "error": "invalid_workbench_settings_request",
                    "message": "pending_invoice_tag_groups must be an object when provided.",
                },
            )
        try:
            updated_payload = self._app_settings_service.update_settings(
                completed_project_ids=[str(item) for item in completed_project_ids],
                bank_account_mappings=[item for item in bank_account_mappings if isinstance(item, dict)],
                allowed_usernames=[str(item).strip() for item in allowed_usernames if str(item).strip()],
                readonly_export_usernames=[
                    str(item).strip() for item in readonly_export_usernames if str(item).strip()
                ],
                admin_usernames=[str(item).strip() for item in admin_usernames if str(item).strip()],
                workbench_column_layouts=workbench_column_layouts,
                oa_retention=oa_retention,
                oa_import=oa_import,
                oa_invoice_offset=oa_invoice_offset,
                bank_transaction_tags=bank_transaction_tags,
                pending_invoice_tag_groups=pending_invoice_tag_groups,
                actor_id=actor_id or "workbench_settings",
                after_bank_transaction_tag_settings_saved=self._finalize_bank_transaction_tag_settings_update,
            )
        except AppSettingsValidationError as exc:
            return self._json_response(
                HTTPStatus.BAD_REQUEST,
                {
                    "error": exc.error_code,
                    "message": str(exc),
                },
            )
        except OARoleSyncError as exc:
            return self._json_response(
                HTTPStatus.BAD_GATEWAY,
                {
                    "error": "oa_role_sync_failed",
                    "message": f"OA 角色同步失败：{exc}",
                },
            )
        except PyMongoError as exc:
            return self._json_response(
                HTTPStatus.SERVICE_UNAVAILABLE,
                {
                    "error": "app_settings_persistence_failed",
                    "message": f"设置保存失败：无法写入 app Mongo，请检查 139.155.5.132:27017 连接后重试。底层错误：{exc}",
                },
            )
        self._invalidate_workbench_read_models()
        if self._state_store is not None:
            self._persist_workbench_read_models_best_effort(
                snapshot=self._workbench_read_model_service.snapshot(),
                operation="invalidate_read_models_after_settings_update",
            )
        self._search_service.clear_cache()
        self._invalidate_search_read_model_scopes(["all"], reason="settings_update")
        if updated_payload.get("oa_invoice_offset") != previous_oa_invoice_offset:
            self._mark_workbench_matching_dirty_scopes(
                self._workbench_query_service.list_available_months(),
                reason="oa_invoice_offset_settings_changed",
            )
        if bank_transaction_tags is not None or pending_invoice_tag_groups is not None:
            self._invalidate_pending_invoice_read_model_scopes(reason="settings_update")
        return self._json_response(HTTPStatus.OK, updated_payload)

    def _handle_api_workbench_settings_oa_manual_search(self, query: dict[str, list[str]]) -> Response:
        service = self._oa_manual_import_service_or_response()
        if isinstance(service, Response):
            return service
        pagination, error = self._parse_oa_manual_search_pagination(query)
        if error is not None:
            return error
        payload = service.search(
            q=query.get("q", [None])[0],
            form_types=self._parse_csv_query_values(query, "form_types"),
            statuses=self._parse_csv_query_values(query, "statuses"),
            date_from=query.get("date_from", [None])[0],
            date_to=query.get("date_to", [None])[0],
            page=pagination["page"],
            page_size=pagination["page_size"],
        )
        return self._json_response(HTTPStatus.OK, payload)

    def _handle_api_workbench_settings_oa_manual_search_refresh_attachments(
        self,
        body: str | bytes | None,
    ) -> Response:
        service = self._oa_manual_import_service_or_response()
        if isinstance(service, Response):
            return service
        payload, error = self._load_json_body(body)
        if error is not None:
            return error
        row_ids, row_ids_error = self._parse_oa_manual_import_row_ids(payload)
        if row_ids_error is not None:
            return row_ids_error
        result = service.refresh_attachments(row_ids)
        self._invalidate_after_oa_manual_import_mutation(result, row_ids=row_ids)
        return self._json_response(HTTPStatus.OK, result)

    def _handle_api_workbench_settings_oa_manual_imports(self) -> Response:
        service = self._oa_manual_import_service_or_response()
        if isinstance(service, Response):
            return service
        return self._json_response(HTTPStatus.OK, service.list_manual_imports())

    def _handle_api_workbench_settings_oa_manual_imports_create(self, body: str | bytes | None) -> Response:
        service = self._oa_manual_import_service_or_response()
        if isinstance(service, Response):
            return service
        payload, error = self._load_json_body(body)
        if error is not None:
            return error
        row_ids, row_ids_error = self._parse_oa_manual_import_row_ids(payload)
        if row_ids_error is not None:
            return row_ids_error
        actor_id = str(payload.get("actor_id") or payload.get("actor") or "workbench_settings").strip()
        normalized_actor_id = actor_id or "workbench_settings"
        if self._import_job_processing_enabled():
            try:
                import_job, event = self._enqueue_import_process_job(
                    import_type="oa_manual_import.create",
                    import_session_id=",".join(sorted(row_ids)),
                    idempotency_key=f"oa_manual_import.create:{normalized_actor_id}:{','.join(sorted(row_ids))}",
                    payload={"row_ids": row_ids, "actor_id": normalized_actor_id},
                    created_by=normalized_actor_id,
                    reason="oa_manual_import_create",
                )
            except RuntimeError as exc:
                return self._json_response(
                    HTTPStatus.SERVICE_UNAVAILABLE,
                    {"error": "import_queue_unavailable", "message": str(exc)},
                )
            return self._json_response(
                HTTPStatus.ACCEPTED,
                {
                    "status": "queued",
                    "import_job": self._serialize_import_job(import_job),
                    "event_id": getattr(event, "event_id", None),
                },
            )
        result = self._execute_oa_manual_import_create(row_ids, actor_id=normalized_actor_id)
        return self._json_response(HTTPStatus.OK, result)

    def _execute_oa_manual_import_create(self, row_ids: list[str], *, actor_id: str) -> dict[str, object]:
        service = self._oa_manual_import_service_or_response()
        if isinstance(service, Response):
            raise RuntimeError("OA manual import service is not available.")
        result = service.import_row_ids(row_ids, actor_id=actor_id)
        self._invalidate_after_oa_manual_import_mutation(result, row_ids=row_ids)
        return result

    def _handle_api_workbench_settings_oa_manual_import_delete(
        self,
        row_id: str,
        body: str | bytes | None,
    ) -> Response:
        service = self._oa_manual_import_service_or_response()
        if isinstance(service, Response):
            return service
        payload: dict[str, object] = {}
        if body:
            payload, error = self._load_json_body(body)
            if error is not None:
                return error
        normalized_row_id = str(row_id or "").strip()
        if not normalized_row_id:
            return self._json_response(
                HTTPStatus.BAD_REQUEST,
                {"error": "invalid_oa_manual_import_request", "message": "row_id is required."},
            )
        actor_id = str(payload.get("actor_id") or payload.get("actor") or "workbench_settings").strip()
        result = service.remove_manual_import(normalized_row_id, actor_id=actor_id or "workbench_settings")
        self._invalidate_after_oa_manual_import_mutation(result, row_ids=[normalized_row_id])
        return self._json_response(HTTPStatus.OK, result)

    def _oa_manual_import_service_or_response(self) -> OAManualImportService | Response:
        service = getattr(self, "_oa_manual_import_service", None)
        if service is None:
            return self._json_response(
                HTTPStatus.SERVICE_UNAVAILABLE,
                {
                    "error": "oa_manual_import_unavailable",
                    "message": "OA 手动导入服务不可用，请检查 OA Mongo 与状态存储配置。",
                },
            )
        return service

    @staticmethod
    def _parse_csv_query_values(query: dict[str, list[str]], key: str) -> list[str] | None:
        raw_values = query.get(key)
        if raw_values is None:
            return None
        values: list[str] = []
        for raw_value in raw_values:
            values.extend(str(part).strip() for part in str(raw_value or "").split(","))
        return [value for value in values if value]

    def _parse_oa_manual_search_pagination(
        self,
        query: dict[str, list[str]],
    ) -> tuple[dict[str, int], Response | None]:
        try:
            page = int(query.get("page", ["0"])[0] or 0)
            page_size = int(query.get("page_size", ["20"])[0] or 20)
        except (TypeError, ValueError):
            return {}, self._invalid_oa_manual_search_request("page and page_size must be integers.")
        if page < 0:
            return {}, self._invalid_oa_manual_search_request("page must be greater than or equal to 0.")
        if page_size < 1 or page_size > 100:
            return {}, self._invalid_oa_manual_search_request("page_size must be between 1 and 100.")
        return {"page": page, "page_size": page_size}, None

    def _invalid_oa_manual_search_request(self, message: str) -> Response:
        return self._json_response(
            HTTPStatus.BAD_REQUEST,
            {"error": "invalid_oa_manual_search_request", "message": message},
        )

    def _parse_oa_manual_import_row_ids(
        self,
        payload: dict[str, object],
    ) -> tuple[list[str], Response | None]:
        row_ids = payload.get("row_ids")
        if not isinstance(row_ids, list):
            return [], self._json_response(
                HTTPStatus.BAD_REQUEST,
                {"error": "invalid_oa_manual_import_request", "message": "row_ids must be an array."},
            )
        normalized = []
        seen: set[str] = set()
        for row_id in row_ids:
            text = str(row_id or "").strip()
            if not text or text in seen:
                continue
            normalized.append(text)
            seen.add(text)
        if not normalized:
            return [], self._json_response(
                HTTPStatus.BAD_REQUEST,
                {"error": "invalid_oa_manual_import_request", "message": "row_ids is required."},
            )
        return normalized, None

    def _invalidate_after_oa_manual_import_mutation(
        self,
        result: dict[str, object],
        *,
        row_ids: list[str],
    ) -> None:
        scope_keys = self._oa_manual_import_affected_scope_keys(result, row_ids=row_ids)
        self._execute_derived_data_lifecycle_event(
            "oa_attachment_invoice_cache_updated",
            scope_keys=scope_keys,
            metadata={"source": "oa_manual_import_mutation"},
        )
        invalidate_records_cache = getattr(self._workbench_query_service._oa_adapter, "invalidate_records_cache", None)
        if callable(invalidate_records_cache):
            invalidate_records_cache([scope_key for scope_key in scope_keys if scope_key != "all"])

    def _oa_manual_import_affected_scope_keys(
        self,
        result: dict[str, object],
        *,
        row_ids: list[str],
    ) -> list[str]:
        scope_keys: set[str] = {"all"}
        rows = result.get("rows") if isinstance(result, dict) else None
        if isinstance(rows, list):
            for row in rows:
                if isinstance(row, dict):
                    month = self._month_from_oa_manual_import_row(row)
                    if month:
                        scope_keys.add(month)
        normalized_row_ids = {str(row_id).strip() for row_id in list(row_ids or []) if str(row_id).strip()}
        if normalized_row_ids:
            for row in self._workbench_query_service.list_record_snapshots():
                if str(row.get("id", "")).strip() in normalized_row_ids:
                    month = str(row.get("_month", "")).strip()
                    if SEARCH_MONTH_RE.match(month):
                        scope_keys.add(month)
            list_application_records_by_row_ids = getattr(
                self._workbench_query_service._oa_adapter,
                "list_application_records_by_row_ids",
                None,
            )
            if callable(list_application_records_by_row_ids):
                try:
                    for record in list_application_records_by_row_ids(sorted(normalized_row_ids)):
                        month = str(getattr(record, "month", "") or "").strip()
                        if SEARCH_MONTH_RE.match(month):
                            scope_keys.add(month)
                except Exception:
                    pass
        return sorted(scope_keys)

    @staticmethod
    def _month_from_oa_manual_import_row(row: dict[str, object]) -> str:
        for key in ("month", "application_date", "apply_date", "date"):
            value = str(row.get(key) or "").strip()
            if len(value) >= 7 and SEARCH_MONTH_RE.match(value[:7]):
                return value[:7]
        for item in list(row.get("items") or []):
            if not isinstance(item, dict):
                continue
            value = str(item.get("date") or "").strip()
            if len(value) >= 7 and SEARCH_MONTH_RE.match(value[:7]):
                return value[:7]
        return ""

    def _handle_api_workbench_settings_projects_sync(self, body: str | bytes | None) -> Response:
        payload, error = self._load_json_body(body)
        if error is not None:
            return error
        actor_id = str(payload.get("actor_id", "")).strip()
        if not actor_id:
            return self._json_response(
                HTTPStatus.BAD_REQUEST,
                {"error": "invalid_project_sync_request", "message": "actor_id is required."},
            )
        try:
            run = self._project_costing_service.sync_projects_from_oa(actor_id=actor_id)
        except Exception as exc:
            return self._json_response(
                HTTPStatus.BAD_GATEWAY,
                {
                    "error": "oa_project_sync_failed",
                    "message": f"OA 项目同步失败：{exc}",
                },
            )
        return self._json_response(
            HTTPStatus.OK,
            {
                "sync": self._serialize_sync_run(run),
                "settings": self._app_settings_service.get_settings_payload(),
            },
        )

    def _handle_api_workbench_settings_project_create(self, body: str | bytes | None) -> Response:
        payload, error = self._load_json_body(body)
        if error is not None:
            return error
        actor_id = str(payload.get("actor_id", "")).strip()
        if not actor_id:
            return self._json_response(
                HTTPStatus.BAD_REQUEST,
                {"error": "invalid_project_create_request", "message": "actor_id is required."},
            )
        try:
            settings_payload = self._app_settings_service.create_manual_project(
                actor_id=actor_id,
                project_code=str(payload.get("project_code", "")),
                project_name=str(payload.get("project_name", "")),
                department_name=payload.get("department_name"),
                owner_name=payload.get("owner_name"),
            )
        except ValueError as exc:
            return self._json_response(
                HTTPStatus.BAD_REQUEST,
                {"error": "invalid_project_create_request", "message": str(exc)},
            )
        return self._json_response(HTTPStatus.OK, {"settings": settings_payload})

    def _handle_api_workbench_settings_project_delete(self, project_id: str) -> Response:
        normalized_project_id = str(project_id).strip()
        if not normalized_project_id:
            return self._json_response(
                HTTPStatus.BAD_REQUEST,
                {"error": "invalid_project_delete_request", "message": "project_id is required."},
            )
        settings_payload = self._app_settings_service.delete_project(normalized_project_id)
        return self._json_response(HTTPStatus.OK, {"settings": settings_payload})

    def _handle_api_workbench_settings_data_reset(
        self,
        body: str | bytes | None,
        headers: dict[str, str] | None,
    ) -> Response:
        payload, error = self._validate_settings_data_reset_request(body, headers)
        if error is not None:
            return error
        action = str(payload.get("action") or "").strip()
        try:
            result = self._execute_settings_data_reset(action)
        except ValueError:
            return self._unsupported_settings_data_reset_response()
        return self._json_response(HTTPStatus.OK, result)

    def _handle_api_workbench_settings_data_reset_job_create(
        self,
        body: str | bytes | None,
        headers: dict[str, str] | None,
    ) -> Response:
        payload, error = self._validate_settings_data_reset_request(body, headers)
        if error is not None:
            return error
        action = str(payload.get("action") or "").strip()
        if action not in self._settings_data_reset_service.supported_actions():
            return self._unsupported_settings_data_reset_response()

        owner_user_id = self._resolve_background_job_owner(headers)
        active_job = self._active_data_reset_background_job(owner_user_id)
        if active_job is not None:
            return self._json_response(
                HTTPStatus.CONFLICT,
                {
                    "error": "settings_data_reset_job_running",
                    "message": "已有数据重置任务正在执行，请等待当前任务完成。",
                    "job": self._serialize_data_reset_background_job(active_job),
                },
            )

        job = self._background_job_service.create_job(
            job_type="settings_data_reset",
            label=self._data_reset_job_label(action),
            owner_user_id=owner_user_id,
            visibility="system",
            phase="queued",
            current=1,
            total=100,
            message="数据重置任务已排队。",
            result_summary={"action": action},
            source={"action": action},
            affected_scopes=["settings", "workbench"],
        )
        self._background_job_service.run_job(job, lambda running_job: self._run_settings_data_reset_background_job(running_job, action))
        return self._json_response(HTTPStatus.ACCEPTED, {"job": self._serialize_data_reset_background_job(job)})

    def _run_settings_data_reset_background_job(self, running_job, action: str) -> dict[str, object]:
        def update(phase: str, message: str, percent: int) -> None:
            self._background_job_service.update_progress(
                running_job.job_id,
                phase=phase,
                message=message,
                current=max(0, min(int(percent), 100)),
                total=100,
                result_summary={"action": action},
            )

        update("start", "数据重置任务已开始。", 1)
        result = self._execute_settings_data_reset(action, progress=update)
        failed = str(result.get("status") or "") == "partial" or str(result.get("rebuild_status") or "") == "failed"
        self._background_job_service.update_progress(
            running_job.job_id,
            phase="failed" if failed else "complete",
            message=str(result.get("message") or ("数据重置失败。" if failed else "数据重置已完成。")),
            current=100,
            total=100,
            result_summary=result,
        )
        if failed:
            self._background_job_service.fail_job(
                running_job.job_id,
                str(result.get("message") or "数据重置失败。"),
                str(result.get("message") or "数据重置失败。"),
            )
        else:
            self._background_job_service.succeed_job(
                running_job.job_id,
                str(result.get("message") or "数据重置已完成。"),
                result_summary=result,
            )
        return result

    def _handle_api_workbench_settings_data_reset_job(
        self,
        job_id: str,
        headers: dict[str, str] | None,
    ) -> Response:
        normalized_job_id = str(job_id or "").strip()
        owner_user_id = self._resolve_background_job_owner(headers)
        try:
            job = self._background_job_service.get_job(normalized_job_id, owner_user_id)
        except (BackgroundJobNotFoundError, BackgroundJobAccessError):
            return self._json_response(
                HTTPStatus.NOT_FOUND,
                {"error": "settings_data_reset_job_not_found", "message": "数据重置任务不存在或已过期。"},
            )
        if job.type != "settings_data_reset":
            return self._json_response(
                HTTPStatus.NOT_FOUND,
                {"error": "settings_data_reset_job_not_found", "message": "数据重置任务不存在或已过期。"},
            )
        return self._json_response(HTTPStatus.OK, {"job": self._serialize_data_reset_background_job(job)})

    def _handle_api_workbench_settings_data_reset_active_job(
        self,
        headers: dict[str, str] | None,
    ) -> Response:
        owner_user_id = self._resolve_background_job_owner(headers)
        active_job = self._active_data_reset_background_job(owner_user_id)
        return self._json_response(
            HTTPStatus.OK,
            {"job": self._serialize_data_reset_background_job(active_job) if active_job is not None else None},
        )

    def _validate_settings_data_reset_request(
        self,
        body: str | bytes | None,
        headers: dict[str, str] | None,
    ) -> tuple[dict[str, object], Response | None]:
        if self._settings_data_reset_service is None:
            return {}, self._json_response(
                HTTPStatus.SERVICE_UNAVAILABLE,
                {
                    "error": "settings_data_reset_unavailable",
                    "message": "当前运行模式未启用持久化状态存储，不能执行数据重置。",
                },
            )
        admin_session, admin_error = self._resolve_admin_session(headers)
        if admin_error is not None:
            return {}, admin_error
        payload, error = self._load_json_body(body)
        if error is not None:
            return {}, error
        action = str(payload.get("action") or "").strip()
        if not action:
            return {}, self._json_response(
                HTTPStatus.BAD_REQUEST,
                {
                    "error": "invalid_workbench_settings_reset_request",
                    "message": "action is required.",
                },
            )
        oa_password = payload.get("oa_password")
        if not isinstance(oa_password, str) or not oa_password:
            return {}, self._oa_password_verification_failed_response()
        password_error = self._verify_reset_oa_password(admin_session, oa_password)
        if password_error is not None:
            return {}, password_error
        return dict(payload), None

    def _unsupported_settings_data_reset_response(self) -> Response:
        return self._json_response(
            HTTPStatus.BAD_REQUEST,
            {
                "error": "invalid_workbench_settings_reset_request",
                "message": "unsupported action.",
                "supported_actions": self._settings_data_reset_service.supported_actions(),
                "protected_targets": self._settings_data_reset_service.protected_targets(),
            },
        )

    def _execute_settings_data_reset(
        self,
        action: str,
        progress: Callable[[str, str, int], None] | None = None,
    ) -> dict[str, object]:
        if progress is not None:
            progress("clear", "正在清理 app 内部状态。", 5)
        service_progress_end = 15 if action == RESET_OA_AND_REBUILD_ACTION else 80

        def service_progress(phase: str, message: str, current: int, total: int) -> None:
            if progress is None:
                return
            safe_total = max(int(total), 1)
            safe_current = max(0, min(int(current), safe_total))
            percent = 5 + round((safe_current / safe_total) * (service_progress_end - 5))
            progress(phase, message, percent)

        try:
            result = self._settings_data_reset_service.execute(action, progress_callback=service_progress)
        except ValueError:
            raise
        if progress is not None:
            reload_percent = 15 if action == RESET_OA_AND_REBUILD_ACTION else 90
            progress("reload", "正在重新载入运行时服务。", reload_percent)
        self._reload_runtime_services()
        if action == RESET_OA_AND_REBUILD_ACTION:
            self._workbench_matching_dirty_scope_service = WorkbenchMatchingDirtyScopeService()
        lifecycle_summary = self._execute_derived_data_lifecycle_event(
            "settings_reset_completed",
            include_all=True,
            metadata={"action": action},
            schedule_cost_warmup=False,
        )
        if action == RESET_OA_AND_REBUILD_ACTION:
            try:
                if progress is not None:
                    progress("rebuild", "正在按 OA 导入设置重新拉取 OA 并重建关联台缓存。", 95)
                self._schedule_or_run_workbench_auto_matching_for_scopes(
                    self._expand_workbench_matching_months(self._workbench_query_service.list_available_months()),
                    reason="oa_reset_rebuild",
                )
                self._build_api_workbench_payload("all")
                result.rebuild_status = "completed"
                result.message = "已按 OA 导入设置重新拉取 OA 并重建关联台，已保留 OA 附件发票解析结果。"
            except Exception as exc:
                result.status = "partial"
                result.rebuild_status = "failed"
                result.message = f"已清空 OA 工作台人工状态并保留 OA 附件发票解析结果，但 OA 重建失败：{exc}"
        if action in {RESET_INVOICES_ACTION, RESET_OA_AND_REBUILD_ACTION}:
            repair_payload = None
            if progress is not None:
                progress("historical_etc_repair", "正在检查历史 ETC 批次恢复状态。", 98)
            try:
                repair_payload = self._maybe_reconcile_historical_etc_repair(
                    reason=f"settings_data_reset:{action}",
                )
            except Exception as exc:
                result.status = "partial"
                result.message = f"{result.message} 历史 ETC 自动恢复失败：{exc}"
            if repair_payload is not None:
                payload_status = str(repair_payload.get("status") or "")
                if payload_status == "attention":
                    result.status = "partial"
                    result.message = f"{result.message} 历史 ETC 批次需要确认或等待前置数据。"
        if progress is not None:
            progress("complete", "数据重置已完成。", 100)
        payload = result.to_payload()
        payload["derived_data_lifecycle"] = lifecycle_summary
        return payload

    def _active_data_reset_job(self) -> DataResetJob | None:
        with self._data_reset_jobs_lock:
            for job in self._data_reset_jobs.values():
                if job.status in {"queued", "running"}:
                    return job
        return None

    def _active_data_reset_background_job(self, owner_user_id: str):
        for job in self._background_job_service.list_active_jobs(owner_user_id, include_system=True):
            if job.type == "settings_data_reset" and job.status in {"queued", "running"}:
                return job
        return None

    @staticmethod
    def _data_reset_job_label(action: str) -> str:
        if action == RESET_BANK_TRANSACTIONS_ACTION:
            return "重置银行流水"
        if action == RESET_INVOICES_ACTION:
            return "重置发票数据"
        if action == RESET_OA_AND_REBUILD_ACTION:
            return "重置OA数据"
        return "数据重置"

    @staticmethod
    def _serialize_data_reset_background_job(job) -> dict[str, object]:
        result = dict(job.result_summary) if isinstance(job.result_summary, dict) else {}
        action = str(job.source.get("action") or result.get("action") or "")
        status = str(job.status)
        legacy_status = {
            "succeeded": "completed",
            "partial_success": "failed",
            "cancelled": "cancelled",
            "acknowledged": "completed",
        }.get(status, status)
        payload: dict[str, object] = {
            "job_id": job.job_id,
            "action": action,
            "status": legacy_status,
            "phase": job.phase,
            "message": job.message,
            "current": job.current,
            "total": job.total,
            "percent": job.percent,
            "created_at": job.created_at,
            "updated_at": job.updated_at,
        }
        if job.error:
            payload["error"] = job.error
        if result and ("cleared_collections" in result or "deleted_counts" in result or legacy_status == "completed"):
            result.setdefault("action", action)
            result.setdefault("status", legacy_status)
            result.setdefault("job_id", job.job_id)
            payload["result"] = result
        return payload

    def _run_settings_data_reset_job(self, job_id: str) -> None:
        def update(phase: str, message: str, percent: int) -> None:
            self._update_data_reset_job(
                job_id,
                status="running",
                phase=phase,
                message=message,
                current=max(0, min(int(percent), 100)),
                total=100,
                percent=max(0, min(int(percent), 100)),
            )

        with self._data_reset_jobs_lock:
            job = self._data_reset_jobs.get(job_id)
            action = job.action if job is not None else ""
        if not action:
            return
        update("start", "数据重置任务已开始。", 1)
        try:
            result = self._execute_settings_data_reset(action, progress=update)
        except Exception as exc:
            self._update_data_reset_job(
                job_id,
                status="failed",
                phase="failed",
                message="数据重置失败。",
                current=100,
                total=100,
                percent=100,
                error=str(exc),
            )
            return

        failed = str(result.get("status") or "") == "partial" or str(result.get("rebuild_status") or "") == "failed"
        self._update_data_reset_job(
            job_id,
            status="failed" if failed else "completed",
            phase="failed" if failed else "complete",
            message=str(result.get("message") or ("数据重置失败。" if failed else "数据重置已完成。")),
            current=100,
            total=100,
            percent=100,
            result=result,
            error=str(result.get("message") or "") if failed else None,
        )

    def _update_data_reset_job(
        self,
        job_id: str,
        *,
        status: str,
        phase: str,
        message: str,
        current: int,
        total: int,
        percent: int,
        result: dict[str, object] | None = None,
        error: str | None = None,
    ) -> None:
        with self._data_reset_jobs_lock:
            job = self._data_reset_jobs.get(job_id)
            if job is None:
                return
            job.status = status
            job.phase = phase
            job.message = message
            job.current = current
            job.total = total
            job.percent = percent
            job.updated_at = datetime.now().isoformat()
            if result is not None:
                job.result = result
            if error is not None:
                job.error = error

    def _parse_oa_attachment_invoices_for_reset_rebuild(
        self,
        *,
        progress: Callable[[str, str, int], None] | None = None,
    ) -> None:
        adapter = self._workbench_query_service._oa_adapter
        parse_attachment_invoices_for_months = getattr(adapter, "parse_attachment_invoices_for_months", None)
        if not callable(parse_attachment_invoices_for_months):
            return
        cutoff_date = self._parse_oa_retention_date(self._app_settings_service.get_oa_retention_cutoff_date())
        if cutoff_date is None:
            months = self._workbench_query_service.list_available_months()
        else:
            months = self._retained_oa_months_for_all_scope(cutoff_date)
        if not months:
            return
        total_months = len(months)
        for index, month in enumerate(months, start=1):
            if progress is not None:
                percent = 20 + int(((index - 1) / total_months) * 70)
                progress("parse_oa_attachments", f"正在解析 OA 附件发票（{index}/{total_months}）：{month}", percent)
            parse_attachment_invoices_for_months([month])
        if progress is not None:
            progress("parse_oa_attachments", f"OA 附件发票解析完成（{total_months}/{total_months}）。", 90)

    def _handle_api_workbench_row_detail(self, row_id: str) -> Response:
        try:
            payload = self._get_api_workbench_row_detail_payload(row_id)
        except KeyError:
            return self._json_response(
                HTTPStatus.NOT_FOUND,
                {"error": "workbench_row_not_found", "row_id": row_id},
            )
        return self._json_response(HTTPStatus.OK, payload)

    def _enforce_admin_access(self, headers: dict[str, str] | None) -> Response | None:
        _, error = self._resolve_admin_session(headers)
        return error

    def _resolve_admin_session(
        self, headers: dict[str, str] | None
    ) -> tuple[OARequestSession | None, Response | None]:
        try:
            session = resolve_oa_request_session(
                headers,
                identity_service=self._oa_identity_service,
                access_control_service=self._access_control_service,
            )
            if not session.can_admin_access:
                return None, self._json_response(
                    HTTPStatus.FORBIDDEN,
                    {
                        "error": "admin_only",
                        "message": "当前账号没有管理员权限，不能执行数据重置。",
                    },
                )
        except UnauthorizedOASessionError as error:
            return None, self._json_response(
                HTTPStatus.UNAUTHORIZED,
                {
                    "error": "invalid_oa_session",
                    "message": str(error) or "缺少 OA 登录态，请从 OA 系统进入。",
                },
            )
        except OASessionExpiredError as error:
            return None, self._json_response(
                HTTPStatus.UNAUTHORIZED,
                {
                    "error": "invalid_oa_session",
                    "message": str(error) or "OA 登录状态已过期。",
                },
            )
        except ForbiddenOAAccessError as error:
            return None, self._json_response(
                HTTPStatus.FORBIDDEN,
                {
                    "error": "forbidden",
                    "message": str(error) or "当前 OA 账户未被授权访问财务运营平台。",
                },
            )
        except OAIdentityConfigurationError as error:
            return None, self._json_response(
                HTTPStatus.SERVICE_UNAVAILABLE,
                {
                    "error": "oa_identity_unavailable",
                    "message": str(error) or "OA 身份服务未配置。",
                },
            )
        except OAIdentityServiceError as error:
            return None, self._json_response(
                HTTPStatus.BAD_GATEWAY,
                {
                    "error": "oa_identity_lookup_failed",
                    "message": str(error) or "OA 身份解析失败。",
                },
            )
        return session, None

    def _verify_reset_oa_password(self, session: OARequestSession | None, oa_password: str) -> Response | None:
        if session is None:
            return self._oa_password_verification_failed_response()
        if session.token == "local-dev-token" and os.getenv("FIN_OPS_DEV_ALLOW_LOCAL_SESSION", "").strip() == "1":
            expected_password = os.getenv("FIN_OPS_DEV_OA_PASSWORD", "local-dev-password")
            if oa_password == expected_password:
                return None
            return self._oa_password_verification_failed_response()
        try:
            if self._oa_identity_service.verify_current_user_password(session.token, oa_password):
                return None
        except OASessionExpiredError as error:
            return self._json_response(
                HTTPStatus.UNAUTHORIZED,
                {
                    "error": "invalid_oa_session",
                    "message": "OA 登录状态已过期。",
                },
            )
        except OAIdentityConfigurationError as error:
            return self._json_response(
                HTTPStatus.SERVICE_UNAVAILABLE,
                {
                    "error": "oa_password_verification_unavailable",
                    "message": "OA 用户密码复核服务未配置。",
                },
            )
        except OAIdentityServiceError as error:
            return self._json_response(
                HTTPStatus.BAD_GATEWAY,
                {
                    "error": "oa_password_verification_unavailable",
                    "message": "OA 用户密码复核服务暂时不可用，请稍后重试。",
                },
            )
        return self._oa_password_verification_failed_response()

    def _oa_password_verification_failed_response(self) -> Response:
        return self._json_response(
            HTTPStatus.FORBIDDEN,
            {
                "error": "oa_password_verification_failed",
                "message": "当前 OA 用户密码复核失败，未执行数据重置。",
            },
        )

    def _get_api_workbench_row_detail_payload(self, row_id: str) -> dict[str, object]:
        etc_summary_row = self._etc_invoice_summary_row_detail(row_id)
        if etc_summary_row is not None:
            payload = {"row": etc_summary_row}
            payload["row"] = self._workbench_override_service.apply_to_row(payload["row"])
            return payload
        try:
            payload = {"row": self._live_workbench_service.get_row_detail(row_id)}
        except KeyError:
            month_hint = self._row_month_scope_from_row_id(row_id)
            cached_rows = self._resolve_rows_from_cached_read_models(
                [row_id],
                month_hint=month_hint,
            )
            if row_id in cached_rows:
                payload = {"row": cached_rows[row_id]}
            elif month_hint is None and self._workbench_query_service._looks_like_oa_row_id(row_id):
                raise KeyError(row_id)
            else:
                payload = self._workbench_api_routes.get_row_detail(row_id)
        payload["row"] = self._workbench_override_service.apply_to_row(payload["row"])
        return payload

    def _handle_api_cost_statistics(self, month: str | None, project_scope: str | None) -> Response:
        current_month = month or datetime.now().strftime("%Y-%m")
        normalized_project_scope = str(project_scope or "active").strip().lower()
        try:
            if normalized_project_scope not in {"active", "all"}:
                raise ValueError("project_scope must be active or all")
            sql_result = self._get_cost_statistics_month_from_sql_read_model(
                current_month,
                normalized_project_scope,
            )
            if sql_result is not None:
                payload, _cache_hit = sql_result
                status = (
                    HTTPStatus.ACCEPTED
                    if payload.get("read_model_status") == "refreshing" and not payload.get("rows")
                    else HTTPStatus.OK
                )
                return self._json_response(status, payload)
            payload = self._cost_statistics_service.get_month_statistics(
                current_month,
                project_scope=normalized_project_scope,
            )
        except ValueError as error:
            return self._cost_statistics_project_scope_error_response(error)
        return self._json_response(HTTPStatus.OK, payload)

    def _handle_api_cost_statistics_explorer(self, month: str | None, project_scope: str | None) -> Response:
        current_month = month or datetime.now().strftime("%Y-%m")
        normalized_project_scope = str(project_scope or "active").strip().lower()
        started_at = monotonic()
        cache_hit = False
        try:
            if normalized_project_scope not in {"active", "all"}:
                raise ValueError("project_scope must be active or all")
            payload, cache_hit = self._get_or_build_cost_statistics_explorer(
                current_month,
                normalized_project_scope,
            )
        except ValueError as error:
            return self._cost_statistics_project_scope_error_response(error)
        self._emit_cost_statistics_explorer_metric(
            month=current_month,
            project_scope=normalized_project_scope,
            cache_hit=cache_hit,
            duration_ms=self._duration_ms(started_at),
            entry_count=self._cost_statistics_explorer_entry_count(payload),
        )
        status = HTTPStatus.ACCEPTED if payload.get("read_model_status") == "refreshing" and not payload.get("time_rows") else HTTPStatus.OK
        return self._json_response(status, payload)

    def _get_or_build_cost_statistics_explorer(
        self,
        month: str,
        project_scope: str,
    ) -> tuple[dict[str, object], bool]:
        sql_result = self._get_cost_statistics_explorer_from_sql_read_model(month, project_scope)
        if sql_result is not None:
            return sql_result
        if self._requires_sql_read_model_runtime():
            scope_key = self._cost_statistics_request_scope_key(month, project_scope)
            self._enqueue_cost_statistics_read_model_refresh(scope_key, reason="api_sql_repository_unavailable")
            payload = self._empty_cost_statistics_explorer_payload(month)
            payload["error"] = "read_model_unavailable"
            payload["read_model_status"] = "refreshing"
            payload["read_model_scope_key"] = scope_key
            return payload, False

        read_model_service = self._cost_statistics_read_model_service
        if read_model_service is not None:
            cached_read_model = read_model_service.get_read_model(month, project_scope)
            if isinstance(cached_read_model, dict):
                cached_payload = cached_read_model.get("payload")
                if isinstance(cached_payload, dict):
                    return cached_payload, True

        if month == "all":
            self._schedule_cost_statistics_cache_warmup(["all"], reason="explorer_all_cache_miss")
            return self._empty_cost_statistics_explorer_payload(month), False

        payload = self._cost_statistics_service.get_explorer(
            month,
            project_scope=project_scope,
        )
        if read_model_service is not None:
            read_model = read_model_service.upsert_read_model(
                month,
                project_scope,
                payload,
                generated_at=datetime.now().isoformat(),
                source_scope_keys=[month],
                cache_status="ready",
            )
            scope_key = self._cost_statistics_read_model_scope_key(month, project_scope, read_model=read_model)
            self._persist_cost_statistics_read_models_best_effort(
                snapshot=read_model_service.snapshot_scope_keys([scope_key]),
                changed_scope_keys=[scope_key],
                operation="upsert_cost_statistics_explorer_read_model",
            )
        return payload, False

    def _get_cost_statistics_explorer_from_sql_read_model(
        self,
        month: str,
        project_scope: str,
    ) -> tuple[dict[str, object], bool] | None:
        repository = getattr(self, "_cost_statistics_sql_read_repository", None)
        get_view = getattr(repository, "get_cost_statistics_view", None)
        if not callable(get_view):
            return None
        scope_key = self._cost_statistics_request_scope_key(month, project_scope)
        expected_source_versions = self._cost_statistics_expected_source_versions(scope_key)
        cache_key = self._cost_statistics_redis_cache_key(scope_key, source_versions=expected_source_versions)
        redis_helper = getattr(getattr(self, "_runtime_repositories", None), "redis_helper", None)
        get_cached = getattr(redis_helper, "get_json", None)
        if callable(get_cached):
            cached = get_cached(cache_key)
            if isinstance(cached, dict):
                cached_payload = cached.get("payload") if isinstance(cached.get("payload"), dict) else cached
                payload = dict(cached_payload)
                payload["read_model_status"] = "fresh"
                payload["read_model_scope_key"] = scope_key
                return payload, True

        view = get_view(scope_key=scope_key)
        if not isinstance(view, dict):
            self._enqueue_cost_statistics_read_model_refresh(scope_key, reason="api_miss")
            payload = self._empty_cost_statistics_explorer_payload(month)
            payload["read_model_status"] = "refreshing"
            payload["read_model_scope_key"] = scope_key
            return payload, False

        payload = dict(view.get("payload") if isinstance(view.get("payload"), dict) else {})
        refresh_status = str(view.get("refresh_status") or "fresh")
        stale_reasons = source_version_mismatch_reasons(
            expected=expected_source_versions,
            actual=view.get("source_versions") if isinstance(view.get("source_versions"), dict) else {},
        )
        if stale_reasons:
            refresh_status = "stale"
        if refresh_status != "fresh":
            self._enqueue_cost_statistics_read_model_refresh(
                scope_key,
                reason="api_source_versions_stale" if stale_reasons else "api_stale",
            )
        payload["read_model_status"] = refresh_status
        payload["read_model_scope_key"] = scope_key
        payload["source_versions"] = view.get("source_versions") if isinstance(view.get("source_versions"), dict) else {}
        if stale_reasons:
            payload["read_model_stale_reasons"] = stale_reasons
        if view.get("generated_at"):
            payload["read_model_generated_at"] = view.get("generated_at")
        set_cached = getattr(redis_helper, "set_json", None)
        if callable(set_cached) and refresh_status == "fresh":
            set_cached(cache_key, {"payload": payload}, ttl_seconds=self._cost_statistics_redis_ttl_seconds())
        return payload, False

    def _get_cost_statistics_month_from_sql_read_model(
        self,
        month: str,
        project_scope: str,
    ) -> tuple[dict[str, object], bool] | None:
        repository = getattr(self, "_cost_statistics_sql_read_repository", None)
        get_view = getattr(repository, "get_cost_statistics_view", None)
        if not callable(get_view):
            return None
        scope_key = self._cost_statistics_request_scope_key(month, project_scope)
        expected_source_versions = self._cost_statistics_expected_source_versions(scope_key)
        cache_key = self._cost_statistics_month_redis_cache_key(scope_key, source_versions=expected_source_versions)
        redis_helper = getattr(getattr(self, "_runtime_repositories", None), "redis_helper", None)
        get_cached = getattr(redis_helper, "get_json", None)
        if callable(get_cached):
            cached = get_cached(cache_key)
            if isinstance(cached, dict):
                cached_payload = cached.get("payload") if isinstance(cached.get("payload"), dict) else cached
                payload = dict(cached_payload)
                payload["read_model_status"] = "fresh"
                payload["read_model_scope_key"] = scope_key
                return payload, True

        view = get_view(scope_key=scope_key)
        if not isinstance(view, dict):
            self._enqueue_cost_statistics_read_model_refresh(scope_key, reason="api_month_miss")
            payload = self._empty_cost_statistics_month_payload(month)
            payload["read_model_status"] = "refreshing"
            payload["read_model_scope_key"] = scope_key
            return payload, False

        explorer_payload = view.get("payload") if isinstance(view.get("payload"), dict) else {}
        payload = self._cost_statistics_month_payload_from_explorer_payload(month, explorer_payload)
        refresh_status = str(view.get("refresh_status") or "fresh")
        stale_reasons = source_version_mismatch_reasons(
            expected=expected_source_versions,
            actual=view.get("source_versions") if isinstance(view.get("source_versions"), dict) else {},
        )
        if stale_reasons:
            refresh_status = "stale"
        if refresh_status != "fresh":
            self._enqueue_cost_statistics_read_model_refresh(
                scope_key,
                reason="api_month_source_versions_stale" if stale_reasons else "api_month_stale",
            )
        payload["read_model_status"] = refresh_status
        payload["read_model_scope_key"] = scope_key
        payload["source_versions"] = view.get("source_versions") if isinstance(view.get("source_versions"), dict) else {}
        if stale_reasons:
            payload["read_model_stale_reasons"] = stale_reasons
        if view.get("generated_at"):
            payload["read_model_generated_at"] = view.get("generated_at")
        set_cached = getattr(redis_helper, "set_json", None)
        if callable(set_cached) and refresh_status == "fresh":
            set_cached(cache_key, {"payload": payload}, ttl_seconds=self._cost_statistics_redis_ttl_seconds())
        return payload, False

    def _cost_statistics_month_payload_from_explorer_payload(
        self,
        month: str,
        explorer_payload: dict[str, object],
    ) -> dict[str, object]:
        time_rows = explorer_payload.get("time_rows")
        if not isinstance(time_rows, list):
            time_rows = []
        grouped: dict[tuple[str, str, str], dict[str, object]] = {}
        transaction_ids: set[str] = set()
        total_amount = Decimal("0.00")
        for raw_row in time_rows:
            if not isinstance(raw_row, dict):
                continue
            amount = self._decimal_from_value(raw_row.get("amount")) or Decimal("0.00")
            transaction_id = str(raw_row.get("transaction_id") or "").strip()
            if transaction_id:
                transaction_ids.add(transaction_id)
            total_amount += amount
            key = (
                str(raw_row.get("project_name") or "").strip(),
                str(raw_row.get("expense_type") or "").strip(),
                str(raw_row.get("expense_content") or "").strip(),
            )
            bucket = grouped.setdefault(
                key,
                {
                    "project_name": key[0],
                    "expense_type": key[1],
                    "expense_content": key[2],
                    "amount_decimal": Decimal("0.00"),
                    "transaction_count": 0,
                    "sample_transaction_ids": [],
                },
            )
            bucket["amount_decimal"] = bucket["amount_decimal"] + amount
            bucket["transaction_count"] = int(bucket["transaction_count"]) + 1
            samples = bucket["sample_transaction_ids"]
            if transaction_id and isinstance(samples, list) and transaction_id not in samples:
                samples.append(transaction_id)

        rows = []
        for bucket in sorted(grouped.values(), key=lambda item: (item["project_name"], item["expense_type"], item["expense_content"])):
            rows.append(
                {
                    "project_name": bucket["project_name"],
                    "expense_type": bucket["expense_type"],
                    "expense_content": bucket["expense_content"],
                    "amount": self._plain_money(bucket["amount_decimal"]),
                    "transaction_count": bucket["transaction_count"],
                    "sample_transaction_ids": list(bucket["sample_transaction_ids"]),
                }
            )
        return {
            "month": month,
            "summary": {
                "row_count": len(rows),
                "transaction_count": len(transaction_ids) if transaction_ids else len(time_rows),
                "total_amount": self._plain_money(total_amount),
            },
            "rows": rows,
        }

    @staticmethod
    def _cost_statistics_request_scope_key(month: str, project_scope: str) -> str:
        return f"{str(project_scope or 'active').strip().lower()}:{str(month or 'all').strip() or 'all'}"

    def _cost_statistics_expected_source_versions(self, scope_key: str) -> dict[str, object]:
        _project_scope, month = str(scope_key or "active:all").split(":", 1)
        return {
            "cost_statistics_read_model_schema_version": COST_STATISTICS_READ_MODEL_SCHEMA_VERSION,
            "workbench_scope_key": month,
            "workbench_read_model_schema_version": WORKBENCH_SQL_PROJECTION_SCHEMA_VERSION,
            "bank_auto_tag_rules_version": self._current_bank_auto_tag_rules_version(),
            "oa_attachment_invoice_parser_version": self._current_oa_attachment_invoice_parser_version(),
            "oa_projection_sync_version": self._current_oa_projection_sync_version(),
        }

    def _cost_statistics_redis_cache_key(
        self,
        scope_key: str,
        *,
        source_versions: dict[str, object] | None = None,
    ) -> str:
        return self._read_model_redis_cache_key(
            "cost_statistics:explorer",
            scope_key,
            schema_version=COST_STATISTICS_READ_MODEL_SCHEMA_VERSION,
            source_versions=source_versions,
        )

    def _cost_statistics_month_redis_cache_key(
        self,
        scope_key: str,
        *,
        source_versions: dict[str, object] | None = None,
    ) -> str:
        return self._read_model_redis_cache_key(
            "cost_statistics:month",
            scope_key,
            schema_version=COST_STATISTICS_READ_MODEL_SCHEMA_VERSION,
            source_versions=source_versions,
        )

    def _read_model_redis_cache_key(
        self,
        prefix: str,
        scope_key: str,
        *,
        schema_version: str,
        source_versions: dict[str, object] | None,
    ) -> str:
        normalized_source_versions = normalize_source_versions(source_versions)
        source_hash = hashlib.sha256(
            json.dumps(
                normalized_source_versions or {"source_versions": "unknown"},
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest()[:16]
        return f"{prefix}:{scope_key}:schema:{schema_version}:sources:{source_hash}"

    @staticmethod
    def _cost_statistics_redis_ttl_seconds() -> int:
        raw_value = os.getenv("FIN_OPS_COST_STATISTICS_REDIS_TTL_SECONDS", "60").strip()
        try:
            return min(120, max(1, int(raw_value)))
        except ValueError:
            return 60

    def _enqueue_cost_statistics_read_model_refresh(self, scope_key: str, *, reason: str) -> bool:
        queue_repository = getattr(getattr(self, "_runtime_repositories", None), "queue_repository", None)
        enqueue = getattr(queue_repository, "enqueue_read_model_refresh", None)
        if not callable(enqueue):
            return False
        enqueue(scope_type="cost_statistics", scope_key=scope_key, reason=reason)
        return True

    @staticmethod
    def _empty_cost_statistics_explorer_payload(month: str) -> dict[str, object]:
        return {
            "month": month,
            "summary": {
                "row_count": 0,
                "transaction_count": 0,
                "total_amount": "0.00",
            },
            "time_rows": [],
            "project_rows": [],
            "expense_type_rows": [],
        }

    @staticmethod
    def _empty_cost_statistics_month_payload(month: str) -> dict[str, object]:
        return {
            "month": month,
            "summary": {
                "row_count": 0,
                "transaction_count": 0,
                "total_amount": "0.00",
            },
            "rows": [],
        }

    @staticmethod
    def _cost_statistics_explorer_entry_count(payload: dict[str, object]) -> int:
        time_rows = payload.get("time_rows")
        if isinstance(time_rows, list):
            return len(time_rows)
        summary = payload.get("summary")
        if isinstance(summary, dict):
            raw_count = summary.get("transaction_count", summary.get("row_count", 0))
            try:
                return int(raw_count)
            except (TypeError, ValueError):
                return 0
        return 0

