    def _handle_api_bank_detail_category_confirmation(
        self,
        transaction_id: str,
        body: str | bytes | None,
        headers: dict[str, str] | None,
    ) -> Response:
        session, auth_error = self._resolve_bank_details_read_session(headers)
        if auth_error is not None:
            return auth_error
        if session is not None and not session.can_mutate_data:
            return self._json_response(
                HTTPStatus.FORBIDDEN,
                {"error": "permission_denied", "message": "当前账户没有确认银行明细标签权限。"},
            )
        payload, error = self._load_json_body(body)
        if error is not None:
            return error
        selected_code = str(
            payload.get("category_code")
            or payload.get("selected_category_code")
            or payload.get("selectedCategoryCode")
            or ""
        ).strip()
        actor_id = (
            session.identity.username or session.identity.user_id
            if session is not None
            else "bank_category_confirmation"
        )
        try:
            suggestion = self._latest_bank_detail_auto_category_suggestion(transaction_id)
            if (
                not isinstance(suggestion, dict)
                or str(suggestion.get("category_resolution_status") or "") != "needs_confirmation"
            ):
                raise BankTransactionCategoryValidationError(
                    "invalid_category_confirmation_candidate",
                    "当前流水没有需要确认的自动标签候选。",
                    transaction_id=transaction_id,
                )
            candidate_codes = [
                str(code).strip()
                for code in list((suggestion or {}).get("auto_candidate_category_codes") or [])
                if str(code or "").strip()
            ]
            if len(set(candidate_codes)) < 2:
                raise BankTransactionCategoryValidationError(
                    "invalid_category_confirmation_candidate",
                    "当前流水没有多个可确认的自动标签候选。",
                    transaction_id=transaction_id,
                )
            result = self._bank_transaction_category_service.confirm_auto_category(
                transaction_id=transaction_id,
                category_code=selected_code,
                candidate_category_codes=candidate_codes,
                rule_version=self._bank_transaction_auto_category_service.current_rule_version(),
                actor=str(actor_id or "bank_category_confirmation"),
            )
        except BankTransactionCategoryValidationError as exc:
            status = HTTPStatus.NOT_FOUND if exc.error_code == "unknown_transaction_id" else HTTPStatus.BAD_REQUEST
            return self._json_response(
                status,
                {"error": exc.error_code, "message": str(exc), "transaction_id": exc.transaction_id},
            )
        affected_months = self._bank_transaction_category_affected_months([transaction_id])
        self._state_store.save_bank_transaction_categories(self._bank_transaction_category_service.snapshot())
        self._after_bank_category_confirmation_mutation(
            transaction_id=transaction_id,
            actor_id=str(actor_id or "bank_category_confirmation"),
            action="bank_detail_category_confirmed",
            affected_months=affected_months,
            metadata={
                "selected_category_code": selected_code,
                "candidate_category_codes": candidate_codes,
            },
        )
        return self._json_response(HTTPStatus.OK, {**result, "affected_months": affected_months})

    def _handle_api_bank_detail_category_confirmation_delete(
        self,
        transaction_id: str,
        headers: dict[str, str] | None,
    ) -> Response:
        session, auth_error = self._resolve_bank_details_read_session(headers)
        if auth_error is not None:
            return auth_error
        if session is not None and not session.can_mutate_data:
            return self._json_response(
                HTTPStatus.FORBIDDEN,
                {"error": "permission_denied", "message": "当前账户没有撤销银行明细标签确认权限。"},
            )
        actor_id = (
            session.identity.username or session.identity.user_id
            if session is not None
            else "bank_category_confirmation"
        )
        try:
            result = self._bank_transaction_category_service.revoke_auto_category_confirmation(
                transaction_id=transaction_id,
                actor=str(actor_id or "bank_category_confirmation"),
            )
        except BankTransactionCategoryValidationError as exc:
            status = HTTPStatus.NOT_FOUND if exc.error_code == "unknown_transaction_id" else HTTPStatus.BAD_REQUEST
            return self._json_response(
                status,
                {"error": exc.error_code, "message": str(exc), "transaction_id": exc.transaction_id},
            )
        affected_months = self._bank_transaction_category_affected_months([transaction_id])
        self._state_store.save_bank_transaction_categories(self._bank_transaction_category_service.snapshot())
        self._after_bank_category_confirmation_mutation(
            transaction_id=transaction_id,
            actor_id=str(actor_id or "bank_category_confirmation"),
            action="bank_detail_category_confirmation_revoked",
            affected_months=affected_months,
            metadata={},
        )
        return self._json_response(HTTPStatus.OK, {**result, "affected_months": affected_months})

    def _latest_bank_detail_auto_category_suggestion(self, transaction_id: str) -> dict[str, object] | None:
        normalized_transaction_id = str(transaction_id or "").strip()
        transaction = self._import_service.get_transaction(normalized_transaction_id)
        row = self._serialize_value(transaction)
        if not isinstance(row, dict):
            row = dict(row or {})
        row["id"] = normalized_transaction_id
        input_row = self._bank_details_service._auto_category_input_row(row)  # noqa: SLF001
        return self._bank_transaction_auto_category_service.suggest_for_rows([input_row]).get(normalized_transaction_id)

    def _after_bank_category_confirmation_mutation(
        self,
        *,
        transaction_id: str,
        actor_id: str,
        action: str,
        affected_months: list[str],
        metadata: dict[str, object],
    ) -> None:
        scope_keys = affected_months or ["all"]
        self._enqueue_bank_detail_read_model_refreshes(scope_keys, reason="bank_detail_category_confirmation_changed")
        self._invalidate_workbench_after_bank_transaction_categories(affected_months)
        self._audit_service.record_action(
            actor_id=actor_id,
            action=action,
            entity_type="bank_transaction_category_confirmation",
            entity_id=str(transaction_id or ""),
            metadata={
                "transaction_id": str(transaction_id or ""),
                "affected_months": list(affected_months or []),
                **dict(metadata),
            },
        )

    def _handle_api_bank_details_transactions_export(
        self,
        query: dict[str, list[str]],
        headers: dict[str, str] | None = None,
    ) -> Response:
        session, auth_error = self._resolve_bank_details_read_session(headers)
        if auth_error is not None:
            return auth_error

        class BankDetailReadModelRefreshing(RuntimeError):
            def __init__(self, payload: dict[str, object]) -> None:
                super().__init__("bank detail read model refreshing")
                self.payload = payload

        def load_accounts(*, date_from: str | None, date_to: str | None) -> dict[str, object]:
            if self._requires_sql_read_model_runtime():
                sql_payload = self._get_bank_detail_accounts_from_sql_read_model(date_from=date_from, date_to=date_to)
                if sql_payload is not None:
                    if sql_payload.get("read_model_status") == "refreshing":
                        raise BankDetailReadModelRefreshing(sql_payload)
                    return sql_payload
            return self._bank_details_service.list_accounts(date_from=date_from, date_to=date_to)

        def load_transactions(
            *,
            account_key: str | None,
            date_from: str | None,
            date_to: str | None,
            keyword: str | None,
            category_code: str | None,
            category_primary_label: str | None,
            category_sub_label: str | None,
            page: int,
            page_size: int,
        ) -> dict[str, object]:
            if self._requires_sql_read_model_runtime():
                sql_payload = self._get_bank_detail_transactions_from_sql_read_model(
                    account_key=account_key,
                    date_from=date_from,
                    date_to=date_to,
                    keyword=keyword,
                    category_code=category_code,
                    category_primary_label=category_primary_label,
                    category_sub_label=category_sub_label,
                    page=page,
                    page_size=page_size,
                )
                if sql_payload is not None:
                    if sql_payload.get("read_model_status") == "refreshing":
                        raise BankDetailReadModelRefreshing(sql_payload)
                    return sql_payload
            return self._bank_details_service.list_transactions(
                account_key=account_key,
                date_from=date_from,
                date_to=date_to,
                keyword=keyword,
                category_code=category_code,
                category_primary_label=category_primary_label,
                category_sub_label=category_sub_label,
                page=page,
                page_size=page_size,
            )

        service = BankDetailsExportService(
            transaction_page_loader=load_transactions,
            account_loader=load_accounts,
        )
        mode = query.get("mode", ["all"])[0]
        account_key = query.get("account_key", [None])[0]
        date_from = query.get("date_from", [None])[0]
        date_to = query.get("date_to", [None])[0]
        keyword = query.get("keyword", [None])[0]
        category_code = query.get("category_code", [None])[0]
        category_primary_label = query.get("category_primary_label", [None])[0]
        category_sub_label = query.get("category_sub_label", [None])[0]
        try:
            result = service.export(
                mode=mode,
                account_key=account_key,
                date_from=date_from,
                date_to=date_to,
                keyword=keyword,
                category_code=category_code,
                category_primary_label=category_primary_label,
                category_sub_label=category_sub_label,
            )
        except BankDetailReadModelRefreshing as exc:
            return self._json_response(HTTPStatus.ACCEPTED, exc.payload)
        except BankDetailsExportError as exc:
            return self._json_response(
                HTTPStatus.BAD_REQUEST,
                {"error": exc.error_code, "message": str(exc)},
            )
        except ValueError as exc:
            return self._json_response(
                HTTPStatus.BAD_REQUEST,
                {"error": "invalid_bank_details_request", "message": str(exc)},
            )

        self._audit_service.record_action(
            actor_id=str(session.identity.username or "bank_detail_export") if session is not None else "bank_detail_export",
            action="bank_detail_export_downloaded",
            entity_type="bank_detail_export",
            entity_id=result.filename,
            metadata={
                "mode": str(mode or "all"),
                "filters": {
                    "account_key": account_key,
                    "date_from": date_from,
                    "date_to": date_to,
                    "keyword": keyword,
                    "category_code": category_code,
                    "category_primary_label": category_primary_label,
                    "category_sub_label": category_sub_label,
                },
                "row_count": result.row_count,
                "sheet_names": result.sheet_names,
                "filename": result.filename,
            },
        )
        return Response(
            status_code=int(HTTPStatus.OK),
            body=result.content,
            headers={
                "Content-Type": XLSX_MIME_TYPE,
                "Content-Disposition": _build_content_disposition(result.filename),
                "Access-Control-Allow-Origin": "*",
                "Access-Control-Allow-Headers": "Content-Type",
                "Access-Control-Allow-Methods": "GET, POST, PUT, PATCH, DELETE, OPTIONS",
                "Access-Control-Expose-Headers": "Content-Disposition",
            },
        )

    def _get_bank_detail_accounts_from_sql_read_model(self, *, date_from: str | None, date_to: str | None) -> dict[str, object] | None:
        repository = getattr(self, "_bank_detail_sql_read_repository", None)
        if repository is None:
            self._enqueue_bank_detail_read_model_refreshes(["all"], reason="api_sql_repository_unavailable")
            return self._bank_detail_accounts_refreshing_payload(
                scope_keys=["all"],
                date_from=date_from,
                date_to=date_to,
            )
        account_balance_loader = getattr(repository, "list_bank_account_balances", None)
        if callable(account_balance_loader):
            try:
                payload = account_balance_loader(date_from=date_from, date_to=date_to)
            except Exception as error:
                if self._is_missing_bank_account_balance_read_model_error(error):
                    self._enqueue_bank_account_balance_read_model_refresh(reason="api_migration_missing")
                    return self._bank_detail_accounts_refreshing_payload(
                        scope_keys=["all"],
                        date_from=date_from,
                        date_to=date_to,
                        scope_summary={
                            "read_model_status": "refreshing",
                            "balance_read_model_status": "missing",
                            "read_model_scope_keys": ["all"],
                            "read_model_error": "bank_account_balance_read_model_not_migrated",
                        },
                    )
                raise
            if not isinstance(payload, dict):
                self._enqueue_bank_account_balance_read_model_refresh(reason="api_miss")
                return self._bank_detail_accounts_refreshing_payload(
                    scope_keys=["all"],
                    date_from=date_from,
                    date_to=date_to,
                )
            payload_status = str(
                payload.get("balance_read_model_status")
                or payload.get("read_model_status")
                or "fresh"
            )
            if payload_status != "fresh" and not (payload.get("accounts") or []):
                self._enqueue_bank_account_balance_read_model_refresh(reason=f"api_{payload_status or 'stale'}")
                return self._bank_detail_accounts_refreshing_payload(
                    scope_keys=["all"],
                    date_from=date_from,
                    date_to=date_to,
                    scope_summary=payload,
                )
            result = dict(payload)
            result["read_model_status"] = payload_status
            result["balance_read_model_status"] = payload_status
            result["cache_status"] = "uncached"
            return result
        scope_keys = self._bank_detail_scope_keys_for_range(date_from=date_from, date_to=date_to)
        scope_summary = self._bank_detail_scope_summary(scope_keys)
        read_model_status = str(scope_summary.get("read_model_status") or "missing")
        if read_model_status == "missing":
            self._enqueue_bank_detail_read_model_refreshes_unless_refreshing(
                scope_keys,
                reason="api_missing",
                scope_summary=scope_summary,
            )
            return self._bank_detail_accounts_refreshing_payload(
                scope_keys=scope_keys,
                date_from=date_from,
                date_to=date_to,
                scope_summary=scope_summary,
            )
        if read_model_status != "fresh":
            self._enqueue_bank_detail_read_model_refreshes_unless_refreshing(
                scope_keys,
                reason=f"api_{read_model_status}",
                scope_summary=scope_summary,
            )
        cache_key = self._bank_detail_redis_cache_key(
            "accounts",
            {
                "date_from": date_from,
                "date_to": date_to,
            },
            scope_summary=scope_summary,
        )
        cached = self._get_bank_detail_cached_payload(cache_key) if read_model_status == "fresh" else None
        if cached is not None:
            cached["cache_status"] = "hit"
            return cached
        loader = getattr(repository, "list_bank_detail_accounts", None)
        if not callable(loader):
            self._enqueue_bank_detail_read_model_refreshes(scope_keys, reason="api_sql_repository_unavailable")
            return self._bank_detail_accounts_refreshing_payload(scope_keys=scope_keys, date_from=date_from, date_to=date_to)
        payload = loader(date_from=date_from, date_to=date_to)
        if not isinstance(payload, dict):
            self._enqueue_bank_detail_read_model_refreshes(scope_keys, reason="api_miss")
            return self._bank_detail_accounts_refreshing_payload(scope_keys=scope_keys, date_from=date_from, date_to=date_to)
        payload_status = str(payload.get("read_model_status") or read_model_status or "fresh")
        if read_model_status != "fresh":
            payload = {**payload, **scope_summary, "read_model_status": read_model_status}
            payload_status = read_model_status
        if payload_status != "fresh" and not (payload.get("accounts") or []):
            self._enqueue_bank_detail_read_model_refreshes_unless_refreshing(
                scope_keys,
                reason=f"api_{payload_status or 'stale'}",
                scope_summary=payload,
            )
            return self._bank_detail_accounts_refreshing_payload(
                scope_keys=scope_keys,
                date_from=date_from,
                date_to=date_to,
                scope_summary=payload,
            )
        result = dict(payload)
        result["read_model_status"] = payload_status
        result["cache_status"] = "miss" if payload_status == "fresh" else "stale"
        if payload_status == "fresh":
            self._set_bank_detail_cached_payload(cache_key, result)
        return result

    def _get_bank_detail_transactions_from_sql_read_model(
        self,
        *,
        account_key: str | None,
        date_from: str | None,
        date_to: str | None,
        keyword: str | None,
        category_code: str | None,
        category_primary_label: str | None,
        category_sub_label: str | None,
        page: int,
        page_size: int,
    ) -> dict[str, object] | None:
        repository = getattr(self, "_bank_detail_sql_read_repository", None)
        normalized_page = max(int(page or 1), 1)
        normalized_page_size = min(max(int(page_size or 100), 1), 100)
        if repository is None:
            self._enqueue_bank_detail_read_model_refreshes(["all"], reason="api_sql_repository_unavailable")
            return self._bank_detail_transactions_refreshing_payload(
                scope_keys=["all"],
                account_key=account_key,
                date_from=date_from,
                date_to=date_to,
                page=normalized_page,
                page_size=normalized_page_size,
            )
        scope_keys = self._bank_detail_scope_keys_for_range(date_from=date_from, date_to=date_to)
        scope_summary = self._bank_detail_scope_summary(scope_keys)
        read_model_status = str(scope_summary.get("read_model_status") or "missing")
        if read_model_status == "missing":
            self._enqueue_bank_detail_read_model_refreshes_unless_refreshing(
                scope_keys,
                reason="api_missing",
                scope_summary=scope_summary,
            )
            return self._bank_detail_transactions_refreshing_payload(
                scope_keys=scope_keys,
                account_key=account_key,
                date_from=date_from,
                date_to=date_to,
                page=normalized_page,
                page_size=normalized_page_size,
                scope_summary=scope_summary,
            )
        if read_model_status != "fresh":
            self._enqueue_bank_detail_read_model_refreshes_unless_refreshing(
                scope_keys,
                reason=f"api_{read_model_status}",
                scope_summary=scope_summary,
            )
        cache_key = self._bank_detail_redis_cache_key(
            "transactions",
            {
                "account_key": account_key,
                "date_from": date_from,
                "date_to": date_to,
                "keyword": keyword,
                "category_code": category_code,
                "category_primary_label": category_primary_label,
                "category_sub_label": category_sub_label,
                "page": normalized_page,
                "page_size": normalized_page_size,
            },
            scope_summary=scope_summary,
        )
        cached = self._get_bank_detail_cached_payload(cache_key) if read_model_status == "fresh" else None
        if cached is not None:
            cached["cache_status"] = "hit"
            return self._with_bank_detail_tag_dictionary(cached)
        loader = getattr(repository, "list_bank_detail_transactions", None)
        if not callable(loader):
            self._enqueue_bank_detail_read_model_refreshes(scope_keys, reason="api_sql_repository_unavailable")
            return self._bank_detail_transactions_refreshing_payload(
                scope_keys=scope_keys,
                account_key=account_key,
                date_from=date_from,
                date_to=date_to,
                page=normalized_page,
                page_size=normalized_page_size,
            )
        payload = loader(
            account_key=account_key,
            date_from=date_from,
            date_to=date_to,
            keyword=keyword,
            category_code=category_code,
            category_primary_label=category_primary_label,
            category_sub_label=category_sub_label,
            page=normalized_page,
            page_size=normalized_page_size,
        )
        if not isinstance(payload, dict):
            self._enqueue_bank_detail_read_model_refreshes(scope_keys, reason="api_miss")
            return self._bank_detail_transactions_refreshing_payload(
                scope_keys=scope_keys,
                account_key=account_key,
                date_from=date_from,
                date_to=date_to,
                page=normalized_page,
                page_size=normalized_page_size,
            )
        payload_status = str(payload.get("read_model_status") or read_model_status or "fresh")
        if read_model_status != "fresh":
            payload = {**payload, **scope_summary, "read_model_status": read_model_status}
            payload_status = read_model_status
        if payload_status != "fresh" and not (payload.get("rows") or []):
            self._enqueue_bank_detail_read_model_refreshes_unless_refreshing(
                scope_keys,
                reason=f"api_{payload_status or 'stale'}",
                scope_summary=payload,
            )
            return self._bank_detail_transactions_refreshing_payload(
                scope_keys=scope_keys,
                account_key=account_key,
                date_from=date_from,
                date_to=date_to,
                page=normalized_page,
                page_size=normalized_page_size,
                scope_summary=payload,
            )
        result = self._with_bank_detail_tag_dictionary(dict(payload))
        result["read_model_status"] = payload_status
        result["cache_status"] = "miss" if payload_status == "fresh" else "stale"
        if payload_status == "fresh":
            self._set_bank_detail_cached_payload(cache_key, result)
        return result

    def _bank_detail_scope_keys_for_range(self, *, date_from: str | None, date_to: str | None) -> list[str]:
        repository = getattr(self, "_bank_detail_sql_read_repository", None)
        scope_key_loader = getattr(repository, "bank_detail_scope_keys_for_range", None)
        if callable(scope_key_loader):
            return list(scope_key_loader(date_from=date_from, date_to=date_to) or ["all"])
        months: set[str] = set()
        for value in (date_from, date_to):
            month = str(value or "")[:7]
            if SEARCH_MONTH_RE.match(month):
                months.add(month)
        return sorted(months) or ["all"]

    def _bank_detail_refresh_scope_keys_from_auto_tag_rules_payload(self, payload: dict[str, object]) -> list[str]:
        refresh_scope = payload.get("refresh_scope") if isinstance(payload.get("refresh_scope"), dict) else {}
        date_from = str(refresh_scope.get("date_from") or "").strip() if isinstance(refresh_scope, dict) else ""
        date_to = str(refresh_scope.get("date_to") or "").strip() if isinstance(refresh_scope, dict) else ""
        if not date_from and not date_to:
            return []
        return [
            scope_key
            for scope_key in self._bank_detail_scope_keys_for_range(
                date_from=date_from or None,
                date_to=date_to or None,
            )
            if scope_key and scope_key != "all"
        ]

    def _bank_detail_scope_summary(self, scope_keys: list[str]) -> dict[str, object]:
        repository = getattr(self, "_bank_detail_sql_read_repository", None)
        summary_loader = getattr(repository, "bank_detail_scope_summary", None)
        if callable(summary_loader):
            summary = summary_loader(scope_keys=scope_keys)
            if isinstance(summary, dict):
                return self._with_bank_detail_auto_tag_rule_freshness(summary)
        return {
            "read_model_status": "missing",
            "read_model_scope_keys": scope_keys,
            "read_model_generated_at": None,
            "read_model_scope_signatures": {},
        }

    def _with_bank_detail_auto_tag_rule_freshness(self, scope_summary: dict[str, object]) -> dict[str, object]:
        if str(scope_summary.get("read_model_status") or "") != "fresh":
            return scope_summary
        expected_version = self._current_bank_auto_tag_rules_version()
        signatures = (
            scope_summary.get("read_model_scope_signatures")
            if isinstance(scope_summary.get("read_model_scope_signatures"), dict)
            else {}
        )
        stale_scope_keys: list[str] = []
        for scope_key, signature in signatures.items():
            if not isinstance(signature, dict):
                stale_scope_keys.append(str(scope_key))
                continue
            source_versions = signature.get("source_versions") if isinstance(signature.get("source_versions"), dict) else {}
            actual_version = self._int_or_none(source_versions.get("bank_auto_tag_rules_version"))
            if actual_version != expected_version:
                stale_scope_keys.append(str(scope_key))
        if not stale_scope_keys:
            return scope_summary
        result = dict(scope_summary)
        result["read_model_status"] = "stale"
        result["read_model_stale_reasons"] = [
            *list(result.get("read_model_stale_reasons") or []),
            "bank_auto_tag_rules_version_mismatch",
        ]
        result["bank_auto_tag_rules_version"] = expected_version
        result["bank_auto_tag_rules_stale_scope_keys"] = stale_scope_keys
        return result

    def _current_bank_auto_tag_rules_version(self) -> int:
        try:
            payload = self._app_settings_service.get_bank_auto_tag_rules_payload(can_save=False)
        except Exception:
            return 1
        return self._int_or_none(payload.get("version")) or 1

    @staticmethod
    def _int_or_none(value: object) -> int | None:
        if value in (None, ""):
            return None
        try:
            return int(value)
        except (TypeError, ValueError):
            return None

    def _bank_detail_accounts_refreshing_payload(
        self,
        *,
        scope_keys: list[str],
        date_from: str | None,
        date_to: str | None,
        scope_summary: dict[str, object] | None = None,
    ) -> dict[str, object]:
        summary = dict(scope_summary or {})
        return {
            "accounts": [],
            "total_balance": None,
            "balance_account_count": 0,
            "missing_balance_account_count": 0,
            "read_model_status": "refreshing",
            **(
                {"balance_read_model_status": summary.get("balance_read_model_status")}
                if summary.get("balance_read_model_status") is not None
                else {}
            ),
            **(
                {"read_model_error": summary.get("read_model_error")}
                if summary.get("read_model_error") is not None
                else {}
            ),
            "read_model_scope_keys": list(summary.get("read_model_scope_keys") or scope_keys),
            "read_model_generated_at": summary.get("read_model_generated_at"),
            "date_from": date_from,
            "date_to": date_to,
            "cache_status": "bypass",
        }

    def _bank_detail_transactions_refreshing_payload(
        self,
        *,
        scope_keys: list[str],
        account_key: str | None,
        date_from: str | None,
        date_to: str | None,
        page: int,
        page_size: int,
        scope_summary: dict[str, object] | None = None,
    ) -> dict[str, object]:
        summary = dict(scope_summary or {})
        return self._with_bank_detail_tag_dictionary(
            {
                "account_key": account_key,
                "date_from": date_from,
                "date_to": date_to,
                "rows": [],
                "category_counts": {"uncategorized": 0},
                "pagination": {"page": page, "page_size": page_size, "total": 0},
                "read_model_status": "refreshing",
                "read_model_scope_keys": list(summary.get("read_model_scope_keys") or scope_keys),
                "read_model_generated_at": summary.get("read_model_generated_at"),
                "cache_status": "bypass",
            }
        )

    def _with_bank_detail_tag_dictionary(self, payload: dict[str, object]) -> dict[str, object]:
        tag_loader = getattr(self._bank_details_service, "_bank_transaction_tags_payload", None)
        if callable(tag_loader):
            payload.setdefault("bank_transaction_tags", tag_loader())
        return payload

    def _enqueue_bank_detail_read_model_refreshes_unless_refreshing(
        self,
        scope_keys: list[str],
        *,
        reason: str,
        scope_summary: dict[str, object],
    ) -> bool:
        if str(scope_summary.get("read_model_status") or "").strip() == "refreshing":
            return False
        return self._enqueue_bank_detail_read_model_refreshes(scope_keys, reason=reason)

    def _enqueue_bank_detail_read_model_refreshes(self, scope_keys: list[str], *, reason: str) -> bool:
        queue_repository = getattr(getattr(self, "_runtime_repositories", None), "queue_repository", None)
        enqueue = getattr(queue_repository, "enqueue_read_model_refresh", None)
        if not callable(enqueue):
            return False
        enqueued = False
        for scope_key in [str(item).strip() for item in list(scope_keys or []) if str(item).strip()]:
            self._delete_bank_detail_redis_cache(scope_key)
            enqueue(scope_type="bank_detail", scope_key=scope_key, reason=reason)
            enqueued = True
        return enqueued

    def _bank_detail_redis_cache_key(self, kind: str, query: dict[str, object], *, scope_summary: dict[str, object]) -> str:
        signature = {
            "kind": kind,
            "query": query,
            "scope_signatures": scope_summary.get("read_model_scope_signatures") or {},
            "schema": "bank_detail:v1",
        }
        digest = hashlib.sha256(json.dumps(signature, ensure_ascii=False, sort_keys=True, default=str).encode("utf-8")).hexdigest()
        return f"bank_detail:{kind}:{digest}"

    def _get_bank_detail_cached_payload(self, cache_key: str) -> dict[str, object] | None:
        redis_helper = getattr(getattr(self, "_runtime_repositories", None), "redis_helper", None)
        get_cached = getattr(redis_helper, "get_json", None)
        if not callable(get_cached):
            return None
        try:
            cached = get_cached(cache_key)
            return dict(cached) if isinstance(cached, dict) else None
        except Exception:
            return None

    def _set_bank_detail_cached_payload(self, cache_key: str, payload: dict[str, object]) -> None:
        redis_helper = getattr(getattr(self, "_runtime_repositories", None), "redis_helper", None)
        set_cached = getattr(redis_helper, "set_json", None)
        if not callable(set_cached):
            return
        try:
            set_cached(cache_key, payload, ttl_seconds=30)
        except Exception:
            return

    def _delete_bank_detail_redis_cache(self, scope_key: str) -> None:
        redis_helper = getattr(getattr(self, "_runtime_repositories", None), "redis_helper", None)
        publish_wakeup = getattr(redis_helper, "publish_wakeup", None)
        if callable(publish_wakeup):
            try:
                publish_wakeup("bank_detail_read_model_refresh", {"scope_key": scope_key})
            except Exception:
                pass

    def _handle_api_import_fact_invoices(self, query: dict[str, list[str]]) -> Response:
        repository = getattr(self._state_store, "import_fact_repository", None)
        page_loader = getattr(repository, "list_invoices_page", None)
        if not callable(page_loader):
            return self._json_response(
                HTTPStatus.NOT_IMPLEMENTED,
                {"error": "sql_import_facts_unavailable", "message": "SQL import fact repository is not configured."},
            )
        try:
            page, page_size = self._pagination_from_query(query)
            rows, total = page_loader(
                page=page,
                page_size=page_size,
                month=query.get("month", [None])[0],
                invoice_type=query.get("invoice_type", [None])[0],
                status=query.get("status", [None])[0],
                keyword=query.get("keyword", [None])[0],
            )
        except ValueError as exc:
            return self._json_response(
                HTTPStatus.BAD_REQUEST,
                {"error": "invalid_import_fact_query", "message": str(exc)},
            )
        return self._json_response(
            HTTPStatus.OK,
            {"items": self._serialize_value(rows), "pagination": {"page": page, "page_size": page_size, "total": total}},
        )

