    @staticmethod
    def _pagination_from_query(query: dict[str, list[str]]) -> tuple[int, int]:
        page = max(int((query.get("page") or ["1"])[0] or 1), 1)
        page_size = min(max(int((query.get("page_size") or ["100"])[0] or 100), 1), 500)
        return page, page_size

