    def _batch_accounting_service(self, *, use_sql_read_model: bool = False) -> BatchAccountingService:
        batch_workbench_loader = None
        if use_sql_read_model and self._workbench_sql_read_repository is not None:
            batch_workbench_loader = self._workbench_sql_read_repository.load_batch_accounting_workbench_payload
        return BatchAccountingService(
            grouped_workbench_loader=lambda month: self._build_api_workbench_payload(month),
            pair_relation_service=self._workbench_pair_relation_service,
            batch_workbench_loader=batch_workbench_loader,
        )

    def _handle_api_batch_accounting(self, query: dict[str, list[str]]) -> Response:
        year = query.get("year", [""])[0]
        bank_year = query.get("bank_year", [year])[0]
        oa_year = query.get("oa_year", [year])[0]
        bucket = query.get("bucket", ["unsubmitted"])[0] or "unsubmitted"
        repair_result = self._repair_batch_accounting_relation_case_ids()
        try:
            payload = self._batch_accounting_service(use_sql_read_model=True).build_payload(
                year=year,
                bank_year=bank_year,
                oa_year=oa_year,
                bucket=bucket,
            )
        except BatchAccountingError as exc:
            return self._batch_accounting_error_response(exc)
        if repair_result.get("changed"):
            payload["repair_result"] = repair_result
        return self._json_response(HTTPStatus.OK, payload)

    def _repair_batch_accounting_relation_case_ids(self) -> dict[str, object]:
        repair_result = self._batch_accounting_service().repair_legacy_case_id_collisions()
        if not repair_result.get("changed"):
            return repair_result
        affected_row_ids = [
            str(row_id)
            for row_id in list(repair_result.get("affected_row_ids") or [])
            if str(row_id).strip()
        ]
        affected_months = {
            str(month)
            for month in list(repair_result.get("affected_months") or [])
            if str(month).strip()
        }
        changed_scope_keys = sorted(
            {
                *affected_months,
                *self._scope_keys_for_row_ids(month="all", row_ids=affected_row_ids, month_scope="all"),
            }
        )
        changed_case_ids = [
            str(case_id)
            for case_id in list(repair_result.get("changed_case_ids") or [])
            if str(case_id).strip()
        ]
        self._schedule_workbench_pair_relation_persist(
            changed_case_ids=changed_case_ids,
            action_name="repair_batch_accounting_relation_case_ids",
        )
        self._execute_derived_data_lifecycle_event(
            "batch_accounting_relation_changed",
            scope_keys=changed_scope_keys,
            metadata={"source": "submit_batch_accounting"},
        )
        self._schedule_workbench_read_model_persist(
            changed_scope_keys=changed_scope_keys,
            action_name="repair_batch_accounting_relation_case_ids",
        )
        return {
            **repair_result,
            "affected_months": changed_scope_keys,
        }

    def _handle_api_batch_accounting_submit(
        self,
        body: str | bytes | None,
        headers: dict[str, str] | None,
    ) -> Response:
        session = self._batch_accounting_mutation_session(headers)
        if isinstance(session, Response):
            return session
        payload, error = self._load_json_body(body)
        if error is not None:
            return error
        actor = str(payload.get("actor") or session.identity.username or session.identity.user_id or "web_finance_user")
        year = str(payload.get("year") or "")
        previous_pair_snapshot = self._workbench_pair_relation_service.snapshot()
        try:
            result = self._batch_accounting_service().submit(
                year=year,
                bank_year=str(payload.get("bank_year") or year),
                oa_year=str(payload.get("oa_year") or year),
                bank_row_id=str(payload.get("bank_row_id") or ""),
                oa_row_ids=list(payload.get("oa_row_ids") or []),
                actor=actor,
                note=str(payload.get("note") or ""),
                expected_version=self._optional_int(payload.get("expected_version")),
            )
        except BatchAccountingError as exc:
            return self._batch_accounting_error_response(exc)
        except (TypeError, ValueError) as exc:
            return self._json_response(
                HTTPStatus.BAD_REQUEST,
                {"error": "invalid_batch_accounting_request", "message": str(exc)},
            )

        changed_scope_keys = sorted(
            self._scope_keys_for_row_ids(
                month="all",
                row_ids=list(result.get("affected_row_ids") or []),
                month_scope=str(result.get("month_scope") or ""),
            )
        )
        changed_case_ids = [str(case_id) for case_id in list(result.get("changed_case_ids") or []) if str(case_id).strip()]
        try:
            self._schedule_workbench_pair_relation_persist(
                changed_case_ids=changed_case_ids,
                action_name="submit_batch_accounting",
            )
        except Exception:
            self._workbench_pair_relation_service = WorkbenchPairRelationService.from_snapshot(previous_pair_snapshot)
            self._configure_workbench_exception_application_service()
            return self._workbench_persistence_unavailable_response(
                StatePersistenceError("工作台关联关系暂时无法保存，请稍后重试。")
            )
        self._execute_derived_data_lifecycle_event(
            "batch_accounting_relation_changed",
            scope_keys=changed_scope_keys,
            metadata={"source": "submit_batch_accounting"},
        )
        self._schedule_workbench_read_model_persist(
            changed_scope_keys=changed_scope_keys,
            action_name="submit_batch_accounting",
        )
        return self._json_response(
            HTTPStatus.OK,
            {
                **result,
                "affected_months": changed_scope_keys,
            },
        )

